1	/**
2	 * Whether a passing verifier run is independent evidence of a change (VERIFIED), or only shows nothing broke
3	 * (REGRESSION_FREE). Rule (accepted 2026-10-13 after the eval pilot's false VERIFIED): a discovered verifier counts as
4	 * independent only when tests that existed before the change, unmodified, failed before it and pass after it —
5	 * fail-before / pass-after. Tests the agent wrote or edited in the same change cannot catch its own misreading of the
6	 * specification, so they never make a change VERIFIED on their own. (An operator-configured verifier is the operator's
7	 * own check and is handled by the caller.)
8	 */
9	
10	import fs from "node:fs";
11	import path from "node:path";
12	import { randomUUID } from "node:crypto";
13	import {
14	  MAX_TEST_BYTES,
15	  SKIP_DIRS,
16	  workspaceRuntimeFiles,
17	  workspaceTestFiles,
18	} from "../tester.js";
19	
20	/** The workspace's verifier run and test files right before the first edit of the current unverified change. */
21	export interface ChangeBaseline {
22	  command: string;
23	  /** The verifier failed (or timed out) before the change. */
24	  failed: boolean;
25	  /** Test files then (workspace-relative path → content); null when one was too large to keep. */
26	  tests: Map<string, string> | null;
27	  /** Verifier configuration and local runner scripts before the change; null means independence is unprovable. */
28	  verifier: Map<string, string> | null;
29	  /**
30	   * Set only when a trusted baseline was captured and its verifier definition could not be bound then (e.g. a local
31	   * node_modules tree). Memory-only: a recovered baseline is never trusted. Its pass is regression evidence at most.
32	   */
33	  verifierUnbindableReason?: string;
34	  /** Operator-declared product scope captured before candidate edits; absent scope cannot establish VERIFIED. */
35	  trustedDeliverables: string[];
36	  /** Exact verifier definition accepted after TDD RED; it is an allowlist for GREEN, never independent evidence. */
37	  tddRedVerifier?: Map<string, string>;
38	  /** Exact contents of tests authored during RED; these must remain unchanged and never enter the pre-change test set. */
39	  tddRedTests?: Map<string, string>;
40	  at: string;
41	}
42	
43	export function trustedDeliverablesFromBaseline(
44	  baseline: ChangeBaseline | null | undefined,
45	): ReadonlySet<string> {
46	  return new Set(baseline?.trustedDeliverables ?? []);
47	}
48	
49	export interface Independence {
50	  independent: boolean;
51	  detail: string;
52	}
53	
54	/** Commands whose acceptance behavior can be redirected by workspace files and therefore needs a pre-turn snapshot. */
55	export function requiresWorkspaceVerifierDefinitionBinding(
56	  command: string,
57	): boolean {
58	  const normalized = command.trim();
59	  return (
60	    // Arbitrary shell `-c` programs can resolve scripts and test definitions
61	    // from the workspace. They are intentionally unsupported by the bounded
62	    // snapshot grammar, so the caller must reject them rather than trust output.
63	    /\b(?:bash|sh|zsh|dash|ksh)\s+(?:-[A-Za-z]*c|--command)\b/.test(
64	      normalized,
65	    ) ||
66	    // Match runner invocations anywhere, including wrappers such as `env npm test`
67	    // and `bash -c 'npm test'`. Unrecognized wrappers deliberately cannot be
68	    // snapshotted and therefore fail closed at completion.
69	    /\b(?:npm|pnpm|yarn)\s+(?:(?:--prefix|--dir)(?:=|\s+)[^\s]+\s+)?(?:(?:run|run-script)\s+)?test\b/.test(
70	      normalized,
71	    ) ||
72	    /\bmake\s+test\b|\bcargo\s+test\b|\bpytest\b|\bpython\d?(?:\.\d+)?\s+-m\s+(?:pytest|unittest)\b|\bgo\s+test\b|\b(?:bun|deno)\s+test\b|\btsx\s+--test\b/.test(
73	      normalized,
74	    ) ||
75	    /\bnode\s+--test\b/.test(normalized) ||
76	    // Direct interpreter scripts can be workspace files even when they have
77	    // no path separator or extension (`node verify`, `sh check`).
78	    /\b(?:node|python\d?(?:\.\d+)?|bash|sh)\s+(?!-)[^\s;&|]+/.test(
79	      normalized,
80	    ) ||
81	    /\b(?:node|python\d?(?:\.\d+)?|bash|sh)\s+(?:\.\.?\/|[\w.-]+\/)[\w./-]+\.(?:mjs|cjs|js|ts|tsx|py|sh)\b/.test(
82	      normalized,
83	    ) ||
84	    /^(?:(?:\.\.?\/)|[A-Za-z0-9_.-]+\/|(?:node|python\d?(?:\.\d+)?|bash|sh)\s+\S+\.(?:mjs|cjs|js|ts|tsx|py|sh))(?:\s|$)/.test(
85	      normalized,
86	    )
87	  );
88	}
89	
90	/** The verifier definition and, when it cannot be bound, why in plain language. */
91	export function snapshotVerifierDefinitionWithReason(
92	  workspace: string,
93	  command: string,
94	  trustedDeliverables: readonly string[] = [],
95	): { verifier: Map<string, string> } | { verifier: null; reason: string } {
96	  const why: { reason?: string } = {};
97	  const verifier = snapshotVerifierDefinition(workspace, command, trustedDeliverables, why);
98	  return verifier ? { verifier } : { verifier: null, reason: why.reason ?? "it has too many or unsupported references" };
99	}
100	
101	/**
102	 * An inline program (`bash -c`, `python -c`, `node -e`, `perl -e`, `ruby -e`) can run any script the candidate rewrote, so
103	 * it is never accepted unbound. Only the interpreter's own options count: scanning stops at the first script, module or
104	 * `--test` argument, so `pytest -c ini`, `python -m pytest -p x` and `./t.sh -c ci` are ordinary verifiers.
105	 */
106	export function isInlineProgramVerifier(command: string): boolean {
107	  return command.slice(0, 512).split(/&&|\|\||[;|]/).some((segment) => {
108	    const tokens = segment.trim().split(/\s+/);
109	    let index = 0;
110	    if (tokens[0] === "env" || tokens[0].endsWith("/env")) {
111	      index = 1;
112	      while (index < tokens.length && (tokens[index].includes("=") || tokens[index].startsWith("-"))) {
113	        index += tokens[index] === "-u" || tokens[index] === "-C" || tokens[index] === "-S" ? 2 : 1;
114	      }
115	    }
116	    const program = (tokens[index] ?? "").slice((tokens[index] ?? "").lastIndexOf("/") + 1);
117	    const options = tokens.slice(index + 1);
118	    const cluster = (option: string) => option.length > 1 && option.startsWith("-") && !option.startsWith("--") && /^-[A-Za-z]+$/.test(option);
119	    const scan = (inline: (option: string, rest: number) => boolean, withArgument: readonly string[], stop: (option: string) => boolean = () => false): boolean => {
120	      for (let n = 0; n < options.length; n++) {
121	        const option = options[n];
122	        if (!option.startsWith("-") && !option.startsWith("+")) return false;
123	        if (stop(option)) return false;
124	        if (inline(option, options.length - n - 1)) return true;
125	        if (withArgument.includes(option)) n++;
126	      }
127	      return false;
128	    };
129	    if (program === "sh" || program === "bash" || program === "zsh" || program === "dash" || program === "ksh") {
130	      return scan((o) => o === "--command" || (cluster(o) && o.includes("c")), ["-o", "+o", "--rcfile", "--init-file"]);
131	    }
132	    if (program.startsWith("python")) {
133	      return scan((o, rest) => cluster(o) && o.endsWith("c") && rest > 0, ["-W", "-X"], (o) => o === "-m");
134	    }
135	    if (program === "node") {
136	      return scan((o) => o === "--eval" || o === "--print" || o.startsWith("--eval=") || o.startsWith("--print=") || o === "-e" || o === "-p" || o === "-pe" || o === "-ep", ["-r", "--require", "--import", "--loader", "--experimental-loader"], (o) => o === "--test" || o.startsWith("--test-"));
137	    }
138	    if (program === "perl" || program === "ruby") return scan((o) => cluster(o) && o.endsWith("e"), ["-I", "-r"]);
139	    return false;
140	  });
141	}
