355	          : baselineProductFiles.has(normalizedDependency)) continue;
356	        if (!add(relative)) return false;
357	        pending.push(dependency);
358	      }
359	    }
360	    return true;
361	  };
362	  const addNpmDefinition = (prefix?: string): boolean => {
