439	    if (!addNpmDefinition(prefix)) return null;
440	    const runtimeDefinitions = runtimeDefinitionFiles(root);
441	    if (!runtimeDefinitions) { note("the workspace has directories nested deeper than 5 levels, an unreadable directory, or more than 128 package.json/tsconfig files"); return null; }
442	    for (const relative of runtimeDefinitions) if (!add(relative)) return null;
443	    files.add("\0runtime-definition-set:" + JSON.stringify(runtimeDefinitions));
444	    files.add(
445	      "\0runtime-product-set:" +
