467	          return null;
468	        }
469	        for (const name of names) {
470	          const resolved = path.resolve(root, path.dirname(rel), name);
471	          if (!resolved.startsWith(root + path.sep) || !fs.existsSync(resolved)) {
472	            note(`a Makefile include (${name}) cannot be resolved inside the workspace`);
473	            return null;
474	          }
475	          pending.push(path.relative(root, resolved));
476	        }
477	      }
478	      if (
479	        !addScriptReferences(makefile, path.resolve(root, path.dirname(rel))) ||
480	        !addNpmInvocations(makefile)
481	      )
482	        return null;
483	    }
484	    if (!targetFound) { note("the Makefile has no test target"); return null; }
485	  } else if (/^cargo\s+test(?:\s|$)/.test(command)) {
486	    const manifest =
487	      command.match(/--manifest-path\s+([^\s]+)/)?.[1] ?? "Cargo.toml";
488	    if (!add(manifest)) return null;
489	    for (const rel of [
490	      "Cargo.lock",
491	      path.join(path.dirname(manifest), "Cargo.lock"),
492	      ".cargo/config",
493	      ".cargo/config.toml",
494	    ]) {
495	      if (fs.existsSync(path.join(root, rel)) && !add(rel)) return null;
496	    }
497	  } else if (
498	    /^(?:pytest|python\d?(?:\.\d+)?\s+-m\s+pytest)(?:\s|$)/.test(command)
499	  ) {
500	    const configs = ["pytest.ini", "pyproject.toml", "setup.cfg", "setup.py"];
501	    const present = configs.filter((rel) =>
502	      fs.existsSync(path.join(root, rel)),
503	    );
504	    if (!present.length) { note("no pytest configuration file was found"); return null; }
505	    for (const rel of present) if (!add(rel)) return null;
506	    if (
507	      !addScriptReferences(
508	        present
509	          .map((rel) => fs.readFileSync(path.join(root, rel), "utf8"))
510	          .join("\n"),
511	      )
512	    )
513	      return null;
514	  } else if (/^go\s+test(?:\s|$)/.test(command)) {
515	    if (!add("go.mod")) return null;
516	    for (const rel of ["go.sum", "vendor/modules.txt"]) {
517	      if (fs.existsSync(path.join(root, rel)) && !add(rel)) return null;
518	    }
519	  } else if (
520	    /^(?:env\s+-u\s+NODE_TEST_CONTEXT\s+)?node\s+--test(?:\s+\S.*)?$/.test(
521	      command,
522	    )
523	  ) {
524	    // The accepted nested Node test runner used by the harness. Bind every
525	    // discovered test file; other wrappers remain unprovable and fail closed.
526	    const tests = snapshotTests(root);
527	    if (!tests || tests.size === 0) { note("there are no existing test files to bind, or one is too large"); return null; }
528	    // Test source is separately snapshotted in ChangeBaseline so changed tests
529	    // can be set aside and the original suite rerun against the code. The
530	    // verifier-definition boundary binds test membership, not mutable bodies.
531	    files.add("\0test-file-set:" + JSON.stringify([...tests.keys()].sort()));
532	  } else {
533	    const script = command.match(
534	      /^(?:node|python\d?(?:\.\d+)?|bash|sh)\s+([^\s]+)(?:\s|$)/,
535	    )?.[1];
536	    if (!script || script.startsWith("-")) { note("the command shape is not one Nexus can snapshot"); return null; }
537	    const relative = path.isAbsolute(script)
538	      ? path.relative(root, script)
539	      : script;
540	    if (!add(relative)) return null;
541	    if (/^(?:node)(?:\s|$)/.test(command.trim())) {
542	      if (
543	        !addLocalDependencyBoundaries(
544	          path.dirname(path.resolve(root, relative)),
545	        )
546	      )
547	        return null;
548	    }
549	    if (
550	      !addScriptReferences(fs.readFileSync(path.join(root, relative), "utf8"))
551	    )
552	      return null;
553	  }
554	
555	  // Capture the product graph for every supported workspace verifier, not only
556	  // npm scripts. Operator-configured `node --test` and direct-script commands
557	  // need the same pre-change source boundary for import-based deliverable proof.
558	  if (![...files].some((file) => file.startsWith("\0runtime-definition-set:"))) {
559	    const runtimeDefinitions = runtimeDefinitionFiles(root);
560	    if (!runtimeDefinitions) { note("the workspace has directories nested deeper than 5 levels, an unreadable directory, or more than 128 package.json/tsconfig files"); return null; }
561	    for (const relative of runtimeDefinitions) if (!add(relative)) return null;
562	    files.add("\0runtime-definition-set:" + JSON.stringify(runtimeDefinitions));
563	  }
564	  if (![...files].some((file) => file.startsWith("\0runtime-product-set:"))) {
565	    files.add(
566	      "\0runtime-product-set:" +
567	        JSON.stringify([...baselineProductFiles].sort()),
568	    );
569	  }
570	
571	  // Snapshot test imports that are not an explicitly scoped deliverable. This
572	  // includes dual-use assertion modules even when runtime-reachable; only the
573	  // operator-declared output paths are allowed to change without invalidating
574	  // the test oracle boundary.
575	  for (const testFile of workspaceTestFiles(root)) {
576	    if (!addTestSupportDependencies(testFile)) return null;
577	  }
578	
579	  const snapshot = new Map<string, string>();
580	  for (const rel of files) {
581	    if (rel.startsWith("\0test-file-set:")) {
582	      snapshot.set(rel, "");
583	      continue;
584	    }
585	    if (rel.startsWith("\0runtime-definition-set:")) {
586	      snapshot.set(rel, "");
587	      continue;
588	    }
589	    if (rel.startsWith("\0runtime-product-set:")) {
590	      snapshot.set(rel, "");
591	      continue;
592	    }
593	    snapshot.set(rel, fs.readFileSync(path.join(root, rel), "utf8"));
594	  }
595	  for (const rel of absentPaths)
596	    snapshot.set("\0must-remain-absent:" + rel, "");
597	  return snapshot;
598	}
