600	/** Whether the verifier's configured command, dependencies, or local entry script changed after its baseline. */
601	export function verifierDefinitionChangedSince(
602	  workspace: string,
603	  baseline: ChangeBaseline,
604	): boolean {
605	  if (!baseline.verifier || baseline.verifier.size === 0) return true;
606	  const root = path.resolve(workspace);
607	  for (const [relative, content] of baseline.verifier) {
608	    if (relative.startsWith("\0test-file-set:")) {
609	      // Test bodies and membership may change; their turn-start bytes are
610	      // captured separately and restored for the independent baseline run.
611	      continue;
612	    }
613	    if (relative.startsWith("\0runtime-definition-set:")) {
614	      const current = runtimeDefinitionFiles(root);
615	      if (!current || JSON.stringify(current) !== relative.slice("\0runtime-definition-set:".length)) return true;
616	      continue;
617	    }
618	    // Preserve the turn-start runtime graph as classification authority. Source
619	    // edits may add valid runtime dependencies, but cannot promote test support
620	    // into a deliverable during the same verification attempt.
621	    if (relative.startsWith("\0runtime-product-set:")) continue;
622	    if (relative.startsWith("\0must-remain-absent:")) {
623	      const target = path.resolve(
624	        root,
625	        relative.slice("\0must-remain-absent:".length),
626	      );
627	      if (!target.startsWith(root + path.sep) || fs.existsSync(target))
628	        return true;
629	      continue;
630	    }
631	    if (relative.startsWith("\0runtime-definition-set:")) continue;
632	    const absolute = path.resolve(root, relative);
633	    if (!absolute.startsWith(`${root}${path.sep}`)) return true;
634	    try {
635	      const stat = fs.lstatSync(absolute);
636	      const real = fs.realpathSync(absolute);
637	      if (
638	        stat.isSymbolicLink() ||
639	        !real.startsWith(`${root}${path.sep}`) ||
640	        !stat.isFile() ||
641	        fs.readFileSync(absolute, "utf8") !== content
642	      )
643	        return true;
644	    } catch {
645	      return true;
646	    }
647	  }
648	  return false;
649	}
650	
651	/** Whether the current verifier definition exactly matches the snapshot validated at the TDD RED boundary. */
652	export function verifierDefinitionMatchesSnapshot(
653	  workspace: string,
654	  command: string,
655	  expected: Map<string, string>,
656	  trustedDeliverables: readonly string[] = [],
657	): boolean {
658	  const current = snapshotVerifierDefinition(workspace, command, trustedDeliverables);
659	  if (!current) return false;
660	  const stableEntries = (snapshot: Map<string, string>) =>
661	    [...snapshot].filter(([relative]) => !relative.startsWith("\0runtime-product-set:")).sort(([a], [b]) => a.localeCompare(b));
662	  const expectedEntries = stableEntries(expected);
663	  const currentEntries = stableEntries(current);
664	  if (currentEntries.length !== expectedEntries.length) return false;
665	  for (let index = 0; index < expectedEntries.length; index++) {
666	    const [expectedPath, expectedContent] = expectedEntries[index];
667	    const [currentPath, currentContent] = currentEntries[index];
668	    if (currentPath !== expectedPath || currentContent !== expectedContent) return false;
669	  }
670	  return true;
671	}
672	
673	/** TDD test files are deliberately excluded from ChangeBaseline.tests, so their bytes need a separate exact check. */
674	export function tddRedTestsMatchSnapshot(
675	  workspace: string,
676	  expected: Map<string, string>,
677	): boolean {
678	  const root = path.resolve(workspace);
679	  for (const [relative, content] of expected) {
680	    const absolute = path.resolve(root, relative);
681	    if (!absolute.startsWith(`${root}${path.sep}`)) return false;
682	    try {
683	      const stat = fs.lstatSync(absolute);
684	      const real = fs.realpathSync(absolute);
685	      if (stat.isSymbolicLink() || !real.startsWith(`${root}${path.sep}`) || !stat.isFile()) return false;
686	      if (fs.readFileSync(absolute, "utf8") !== content) return false;
687	    } catch {
688	      return false;
689	    }
690	  }
691	  return true;
692	}
693	
694	/** A new workspace-local npm dependency tree changes executable resolution after the baseline. */
695	export function npmDependencyBoundaryChangedSince(
696	  workspace: string,
697	  baseline: ChangeBaseline,
698	): boolean {
699	  if (!baseline.verifier) return true;
700	  const root = path.resolve(workspace);
701	  return [...baseline.verifier.keys()].some((key) => {
702	    if (!key.startsWith("\0must-remain-absent:")) return false;
703	    const relative = key.slice("\0must-remain-absent:".length);
704	    if (path.basename(relative) !== "node_modules") return false;
705	    return fs.existsSync(path.resolve(root, relative));
706	  });
707	}
708	
709	/** Whether any test file was added, removed or changed since the baseline. */
710	export function testsChangedSince(
711	  workspace: string,
712	  baseline: Map<string, string>,
713	): boolean {
714	  const now = snapshotTests(workspace);
715	  if (!now || now.size !== baseline.size) return true;
716	  for (const [file, content] of now)
717	    if (baseline.get(file) !== content) return true;
718	  return false;
719	}
720	
721	/** What a passing, deliverable-covering run of `command` shows, given the baseline (no extra run needed). */
722	export function judgeWithoutCopy(
723	  workspace: string,
724	  command: string,
725	  baseline: ChangeBaseline | null | undefined,
726	): Independence | "needs-copy" {
727	  if (!baseline || baseline.command !== command) {
728	    return {
729	      independent: false,
730	      detail: `no run of ${command} before this change was recorded, so nothing shows the tests exercise the change`,
731	    };
732	  }
733	  const verifierChanged = verifierDefinitionChangedSince(workspace, baseline);
734	  if (!baseline.verifier || baseline.verifier.size === 0) {
735	    return {
736	      independent: false,
737	      detail:
738	        "the pre-change verifier definition was not captured, so its test summary cannot establish independent evidence",
739	    };
740	  }
741	  const changed =
742	    !baseline.tests || testsChangedSince(workspace, baseline.tests);
743	  if (!baseline.failed) {
744	    return {
745	      independent: false,
746	      detail: changed
747	        ? "the existing tests passed before the change too; the new behaviour is checked only by tests Nexus wrote"
748	        : "the existing tests passed before the change too, so they do not show the change",
749	    };
750	  }
751	  if (npmDependencyBoundaryChangedSince(workspace, baseline)) {
752	    return {
753	      independent: false,
754	      detail:
755	        "a workspace-local npm dependency tree appeared after the baseline; its executable and package contents are not independently bound",
756	    };
757	  }
758	  if (!changed && !verifierChanged)
759	    return {
760	      independent: true,
761	      detail: "tests that failed before the change pass after it",
762	    };
763	  if (!baseline.tests)
764	    return {
765	      independent: false,
766	      detail:
767	        "Nexus changed test files that were too large to set aside, so its own test edits cannot be excluded",
768	    };
769	  return "needs-copy";
770	}
771	
772	const MAX_COPY_FILES = 20_000;
773	
774	/**
775	 * A copy of the workspace (dependency and build directories linked, not copied) with the test files as they were at
776	 * the baseline: tests the change added are removed, tests it edited are restored. Under `.nexus/verify/`, so it stays
777	 * inside the workspace's sandbox. Returns null when the workspace is too large to copy.
778	 */
779	export function prepareBaselineTestsCopy(
780	  workspace: string,
781	  tests: Map<string, string>,
782	  verifier: Map<string, string>,
783	): string | null {
784	  const root = path.resolve(workspace);
785	  const dir = path.join(root, ".nexus", "verify", randomUUID());
786	  let files = 0;
787	  const copy = (from: string, to: string): boolean => {
788	    fs.mkdirSync(to, { recursive: true });
789	    for (const entry of fs.readdirSync(from, { withFileTypes: true })) {
790	      const src = path.join(from, entry.name);
791	      const dst = path.join(to, entry.name);
792	      if (from === root && entry.name === ".nexus") continue;
793	      if (
794	        entry.isDirectory() &&
795	        SKIP_DIRS.has(entry.name) &&
796	        entry.name !== ".git"
797	      ) {
798	        fs.symlinkSync(src, dst, "dir");
799	      } else if (entry.isDirectory()) {
800	        if (entry.name === ".git") continue;
801	        if (!copy(src, dst)) return false;
802	      } else if (entry.isSymbolicLink()) {
803	        let realTarget: string;
804	        let targetIsDirectory: boolean;
805	        try {
806	          realTarget = fs.realpathSync(src);
807	          targetIsDirectory = fs.statSync(src).isDirectory();
808	        } catch {
809	          return false;
810	        }
811	        const relativeTarget = path.relative(root, realTarget);
812	        if (
813	          relativeTarget === ".." ||
814	          relativeTarget.startsWith(`..${path.sep}`) ||
815	          path.isAbsolute(relativeTarget)
816	        )
817	          return false;
818	        if (++files > MAX_COPY_FILES) return false;
819	        const linkTarget = fs.readlinkSync(src);
820	        const rebasedTarget = path.isAbsolute(linkTarget)
821	          ? path.join(dir, path.relative(root, realTarget))
822	          : linkTarget;
823	        fs.symlinkSync(rebasedTarget, dst, targetIsDirectory ? "dir" : "file");
824	      } else if (entry.isFile()) {
825	        if (++files > MAX_COPY_FILES) return false;
826	        fs.copyFileSync(src, dst);
827	      }
828	    }
829	    return true;
830	  };
831	  try {
832	    if (!copy(root, dir)) {
833	      fs.rmSync(dir, { recursive: true, force: true });
834	      return null;
835	    }
836	    for (const file of workspaceTestFiles(dir)) {
837	      if (!tests.has(path.relative(dir, file)))
838	        fs.rmSync(file, { force: true });
839	    }
840	    for (const [rel, content] of tests) {
841	      fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
842	      fs.writeFileSync(path.join(dir, rel), content);
843	    }
844	    for (const [rel, content] of verifier) {
845	    if (
846	      rel.startsWith("\0runtime-definition-set:") ||
847	      rel.startsWith("\0runtime-product-set:")
848	    ) continue;
849	      if (rel.startsWith("\0must-remain-absent:")) {
850	        const absent = rel.slice("\0must-remain-absent:".length);
851	        const destination = path.resolve(dir, absent);
852	        if (!destination.startsWith(dir + path.sep))
853	          throw new Error("verifier absence path escaped workspace");
854	        if (
855	          path.basename(absent) === "node_modules" &&
856	          fs.existsSync(destination)
857	        )
858	          throw new Error("mutable npm dependencies appeared after baseline");
859	        fs.rmSync(destination, { recursive: true, force: true });
860	        continue;
861	      }
862	      const destination = path.resolve(dir, rel);
863	      if (!destination.startsWith(`${dir}${path.sep}`))
864	        throw new Error("verifier path escaped workspace");
865	      fs.mkdirSync(path.dirname(destination), { recursive: true });
866	      fs.writeFileSync(destination, content);
867	    }
868	    return dir;
869	  } catch {
870	    fs.rmSync(dir, { recursive: true, force: true });
871	    return null;
872	  }
873	}
