143	/** Test files of the workspace by relative path, or null when one exceeds the size kept for restoring. */
144	export function snapshotTests(workspace: string): Map<string, string> | null {
145	  const root = path.resolve(workspace);
146	  const tests = new Map<string, string>();
147	  for (const file of workspaceTestFiles(root)) {
148	    const stat = fs.statSync(file);
149	    if (stat.size > MAX_TEST_BYTES) return null;
150	    tests.set(path.relative(root, file), fs.readFileSync(file, "utf8"));
151	  }
152	  return tests;
153	}
