155	function runtimeDefinitionFiles(workspace: string): string[] | null {
156	  const root = path.resolve(workspace);
157	  const found: string[] = [];
158	  const walk = (directory: string, depth: number): boolean => {
159	    if (depth > 5 || found.length >= 128) return false;
160	    let entries: fs.Dirent[];
161	    try { entries = fs.readdirSync(directory, { withFileTypes: true }); } catch { return false; }
162	    for (const entry of entries) {
163	      if (["node_modules", ".git", "dist", "build"].includes(entry.name)) continue;
164	      const absolute = path.join(directory, entry.name);
165	      if (entry.isDirectory()) {
166	        if (!walk(absolute, depth + 1)) return false;
167	      } else if (entry.isFile() && (entry.name === "package.json" || /^tsconfig(?:\.[^/]+)?\.json$/.test(entry.name))) {
168	        found.push(path.relative(root, absolute).replace(/\\/g, "/"));
169	        if (found.length > 128) return false;
170	      }
171	    }
172	    return true;
173	  };
174	  return walk(root, 0) ? found.sort() : null;
175	}
