177	/**
178	 * Files which define a discovered verifier. A passing summary is candidate-controlled output, so it can only
179	 * contribute to an independent judgement when the command definition that produced it is unchanged. The bounded
180	 * list covers the repository's supported verifier entry points and local scripts named by their configuration.
181	 * Unknown verifier commands fail closed rather than treating their output as independently authenticated.
182	 */
183	export function snapshotVerifierDefinition(
184	  workspace: string,
185	  command: string,
186	  trustedDeliverables: readonly string[] = [],
187	  why?: { reason?: string },
188	): Map<string, string> | null {
189	  const root = path.resolve(workspace);
190	  const note = (reason: string): false => {
191	    if (why && !why.reason) why.reason = reason;
192	    return false;
193	  };
194	  const baselineProductFiles = workspaceRuntimeFiles(root);
195	  const trustedSet = new Set(trustedDeliverables);
196	  const files = new Set<string>();
197	  const absentPaths = new Set<string>();
198	  const add = (relative: string) => {
199	    const absolute = path.resolve(root, relative);
200	    if (!absolute.startsWith(`${root}${path.sep}`)) return note("it references a path outside the workspace");
201	    try {
202	      const linkStat = fs.lstatSync(absolute);
203	      const real = fs.realpathSync(absolute);
204	      if (linkStat.isSymbolicLink() || !real.startsWith(`${root}${path.sep}`))
205	        return note(`${relative} is a symlink or leaves the workspace`);
206	      const stat = fs.statSync(absolute);
207	      if (!stat.isFile() || stat.size > MAX_TEST_BYTES) return note(`${relative} is not a regular file or is too large`);
208	      files.add(path.relative(root, absolute));
209	      return true;
210	    } catch {
211	      return note(`${relative} is missing or unreadable`);
212	    }
213	  };
214	  const scanReferences = (text: string, base: string, pending: string[]) => {
215	    const pattern =
216	      /(?:^|[\s"'=])((?:\.\.?\/|[\w.-]+\/)[\w./@+-]+|[\w.@+-]+\.(?:mjs|cjs|js|ts|tsx|sh|bash|py|ps1))(?=$|[\s"'*])/gm;
217	    for (const match of text.matchAll(pattern)) {
218	      const candidate = match[1].replace(/^\.\//, "");
219	      const resolved = path.resolve(base, candidate);
220	      if (!resolved.startsWith(`${root}${path.sep}`)) return note("it references a path outside the workspace");
221	      if (fs.existsSync(resolved)) pending.push(resolved);
222	      else absentPaths.add(path.relative(root, resolved));
223	    }
224	    return true;
225	  };
226	  const addScriptReferences = (text: string, base = root) => {
227	    const pending: string[] = [];
228	    const baselineTestFiles = new Set(
229	      workspaceTestFiles(root).map((file) =>
230	        path.relative(root, file).replace(/\\/g, "/"),
231	      ),
232	    );
233	    if (!scanReferences(text, base, pending)) return false;
234	    // Bare script arguments are paths to Node/Python/shell interpreters even
235	    // without a slash or extension (`node verify`, `sh ci-check`). Bind or
236	    // absence-track only arguments in this interpreter position; arbitrary
237	    // bare command names remain operator/system command resolution.
238	    const interpreterScript =
239	      /(?:^|[\s;&|])(?:node|python\d?(?:\.\d+)?|bash|sh)\s+([^\s;&|]+)/g;
240	    for (const match of text.matchAll(interpreterScript)) {
241	      const script = match[1].replace(/^["']|["']$/g, "");
242	      if (script.startsWith("-")) continue;
243	      const resolved = path.resolve(base, script);
244	      if (!resolved.startsWith(`${root}${path.sep}`)) return note("it references a path outside the workspace");
245	      if (fs.existsSync(resolved)) pending.push(resolved);
246	      else absentPaths.add(path.relative(root, resolved));
247	    }
248	    const visited = new Set<string>();
249	    while (pending.length) {
250	      const file = pending.pop()!;
251	      if (visited.has(file)) continue;
252	      visited.add(file);
253	      const relative = path.relative(root, file).replace(/\\/g, "/");
254	      if (baselineTestFiles.has(relative)) {
255	        // Test bodies are captured separately for fail-before/pass-after
256	        // adjudication. Following their product imports here would bind the
257	        // implementation under test as part of the verifier definition and
258	        // reject every legitimate product edit as verifier drift.
259	        files.add(
260	          "\0test-file-set:" + JSON.stringify([...baselineTestFiles].sort()),
261	        );
262	        continue;
263	      }
264	      if (visited.size > 128) return note("it references more than 128 files");
265	      if (!add(path.relative(root, file))) return false;
266	      const contents = fs.readFileSync(file, "utf8");
267	      if (!scanReferences(contents, path.dirname(file), pending)) return false;
268	    }
269	    return true;
270	  };
271	  const addLocalDependencyBoundaries = (start: string) => {
272	    for (
273	      let current = path.resolve(start);
274	      current.startsWith(root);
275	      current = path.dirname(current)
276	    ) {
277	      const dependencies = path.join(current, "node_modules");
278	      if (fs.existsSync(dependencies)) return note("the workspace has a local node_modules directory");
279	      absentPaths.add(path.relative(root, dependencies));
280	      if (current === root) break;
281	    }
282	    return true;
283	  };
284	  const addTestSupportDependencies = (testFile: string): boolean => {
285	    const pending = [testFile];
286	    const visited = new Set<string>();
287	    const extensions = [
288	      "",
289	      ".js",
290	      ".cjs",
291	      ".mjs",
292	      ".ts",
293	      ".tsx",
294	      ".jsx",
295	      ".json",
296	    ];
297	    while (pending.length) {
298	      const current = pending.pop()!;
299	      if (visited.has(current)) continue;
300	      visited.add(current);
301	      if (visited.size > 256) return note("a test imports more than 256 local files");
302	      let text: string;
303	      try {
304	        text = fs.readFileSync(current, "utf8");
305	      } catch {
306	        return note(`${path.relative(root, current)} is unreadable`);
307	      }
308	      const specifiers = new Set<string>();
309	      const importPattern =
310	        /(?:\bfrom\s*|\bimport\s*\(|\brequire\s*\()\s*["']([^"']+)["']|(?:^|[;\n])\s*import\s*["']([^"']+)["']/gm;
311	      for (const match of text.matchAll(importPattern)) {
312	        const specifier = match[1] ?? match[2];
313	        if (specifier.startsWith(".")) specifiers.add(specifier);
314	      }
315	      for (const specifier of specifiers) {
316	        const base = path.resolve(path.dirname(current), specifier);
317	        if (!base.startsWith(`${root}${path.sep}`)) return note("a test imports a path outside the workspace");
318	        const candidates = new Set<string>();
319	        if (/\.(?:c|m)?js$/.test(base)) {
320	          candidates.add(base.replace(/\.(?:c|m)?js$/, ".ts"));
321	          candidates.add(base.replace(/\.(?:c|m)?js$/, ".tsx"));
322	        }
323	        for (const extension of extensions) {
324	          candidates.add(base + extension);
325	          for (const indexExtension of extensions.slice(1)) {
326	            candidates.add(
327	              path.join(base + extension, `index${indexExtension}`),
328	            );
329	          }
330	        }
331	        const existing = [...candidates].filter((candidate) => {
332	          try {
333	            return fs.statSync(candidate).isFile();
334	          } catch {
335	            return false;
336	          }
337	        });
338	        const supportRelative = path.relative(root, base);
339	        const normalizedSupport = supportRelative.replace(/\\/g, "/");
340	        const supportReference = trustedSet.size > 0
341	          ? !trustedSet.has(normalizedSupport)
342	          : !baselineProductFiles.has(normalizedSupport);
343	        if (existing.length === 0) {
344	          if (supportReference) {
345	            absentPaths.add(path.relative(root, base));
346	          }
347	          continue;
348	        }
349	        if (existing.length > 1) return note(`a test import (${normalizedSupport}) is ambiguous`);
350	        const dependency = existing[0];
351	        const relative = path.relative(root, dependency);
352	        const normalizedDependency = relative.replace(/\\/g, "/");
353	        if (trustedSet.size > 0
354	          ? trustedSet.has(normalizedDependency)
355	          : baselineProductFiles.has(normalizedDependency)) continue;
356	        if (!add(relative)) return false;
357	        pending.push(dependency);
358	      }
359	    }
360	    return true;
361	  };
362	  const addNpmDefinition = (prefix?: string): boolean => {
363	    const packageFile = path.join(prefix ?? ".", "package.json");
364	    if (!add(packageFile)) return false;
365	    const packageRoot = path.resolve(root, path.dirname(packageFile));
366	    // A lockfile describes intended packages, not the bytes in mutable node_modules. Until a trusted immutable
367	    // dependency runner is available, local npm dependencies cannot establish independent verification.
368	    // Bind their absence too, so a candidate cannot add a fake .bin launcher after the baseline.
369	    if (!addLocalDependencyBoundaries(packageRoot)) return false;
370	    const npmrc = path.join(path.dirname(packageFile), ".npmrc");
371	    if (fs.existsSync(path.join(root, npmrc))) {
372	      const npmrcPath = path.resolve(root, npmrc);
373	      if (!npmrcPath.startsWith(`${root}${path.sep}`)) return note(".npmrc is outside the workspace");
374	      let npmrcContents: string;
375	      try {
376	        const stat = fs.lstatSync(npmrcPath);
377	        const real = fs.realpathSync(npmrcPath);
378	        if (
379	          stat.isSymbolicLink() ||
380	          !real.startsWith(`${root}${path.sep}`) ||
381	          !stat.isFile() ||
382	          stat.size > MAX_TEST_BYTES
383	        ) return note(".npmrc is a symlink, not a regular file, or too large");
384	        npmrcContents = fs.readFileSync(npmrcPath, "utf8");
385	      } catch {
386	        return note(".npmrc is unreadable");
387	      }
388	      // npm auth values may be short, unquoted, and therefore invisible to the
389	      // generic entropy and assignment redactors. Never copy a credential-bearing
390	      // npmrc into durable verifier state; the caller will fail closed because
391	      // this verifier definition cannot be safely bound.
392	      if (/\b(?:_auth(?:token)?|_password|password|username)\s*(?:=|:)/i.test(npmrcContents)) {
393	        return note(".npmrc holds credentials");
394	      }
395	      if (!add(npmrc)) return false;
396	    } else {
397	      absentPaths.add(npmrc);
398	    }
399	    let testScript: unknown;
400	    try {
401	      testScript = JSON.parse(
402	        fs.readFileSync(path.join(root, packageFile), "utf8"),
403	      )?.scripts?.test;
404	    } catch {
405	      return note("package.json is not valid JSON");
406	    }
407	    if (typeof testScript !== "string" || !testScript.trim()) return note("package.json has no test script");
408	    if (
409	      !addScriptReferences(
410	        testScript,
411	        path.resolve(root, path.dirname(packageFile)),
412	      )
413	    )
414	      return false;
415	    for (const lock of [
416	      "package-lock.json",
417	      "npm-shrinkwrap.json",
418	      "pnpm-lock.yaml",
419	      "yarn.lock",
420	    ]) {
421	      const rel = path.join(path.dirname(packageFile), lock);
422	      if (fs.existsSync(path.join(root, rel)) && !add(rel)) return false;
423	    }
424	    return true;
425	  };
426	  const addNpmInvocations = (text: string): boolean => {
427	    const pattern =
428	      /\b(?:npm|pnpm|yarn)(?:\s+(?:--prefix|--dir)(?:=|\s+)([^\s]+))?\s+(?:(?:run|run-script)\s+)?test\b/g;
429	    for (const match of text.matchAll(pattern)) {
430	      // The package script is common to the supported package managers. Its
431	      // dependency tree is separately required to remain absent or immutable.
432	      if (!addNpmDefinition(match[1])) return false;
433	    }
434	    return true;
435	  };
