600	/** Whether the verifier's configured command, dependencies, or local entry script changed after its baseline. */
601	export function verifierDefinitionChangedSince(
602	  workspace: string,
603	  baseline: ChangeBaseline,
604	): boolean {
605	  if (!baseline.verifier || baseline.verifier.size === 0) return true;
606	  const root = path.resolve(workspace);
607	  for (const [relative, content] of baseline.verifier) {
608	    if (relative.startsWith("\0test-file-set:")) {
609	      // Test bodies and membership may change; their turn-start bytes are
610	      // captured separately and restored for the independent baseline run.
611	      continue;
612	    }
613	    if (relative.startsWith("\0runtime-definition-set:")) {
614	      const current = runtimeDefinitionFiles(root);
615	      if (!current || JSON.stringify(current) !== relative.slice("\0runtime-definition-set:".length)) return true;
616	      continue;
617	    }
618	    // Preserve the turn-start runtime graph as classification authority. Source
619	    // edits may add valid runtime dependencies, but cannot promote test support
620	    // into a deliverable during the same verification attempt.
621	    if (relative.startsWith("\0runtime-product-set:")) continue;
622	    if (relative.startsWith("\0must-remain-absent:")) {
623	      const target = path.resolve(
624	        root,
625	        relative.slice("\0must-remain-absent:".length),
626	      );
627	      if (!target.startsWith(root + path.sep) || fs.existsSync(target))
628	        return true;
629	      continue;
630	    }
631	    if (relative.startsWith("\0runtime-definition-set:")) continue;
632	    const absolute = path.resolve(root, relative);
633	    if (!absolute.startsWith(`${root}${path.sep}`)) return true;
634	    try {
635	      const stat = fs.lstatSync(absolute);
636	      const real = fs.realpathSync(absolute);
637	      if (
638	        stat.isSymbolicLink() ||
639	        !real.startsWith(`${root}${path.sep}`) ||
640	        !stat.isFile() ||
641	        fs.readFileSync(absolute, "utf8") !== content
642	      )
643	        return true;
644	    } catch {
645	      return true;
646	    }
647	  }
648	  return false;
649	}
