651	/** Whether the current verifier definition exactly matches the snapshot validated at the TDD RED boundary. */
652	export function verifierDefinitionMatchesSnapshot(
653	  workspace: string,
654	  command: string,
655	  expected: Map<string, string>,
656	  trustedDeliverables: readonly string[] = [],
657	): boolean {
658	  const current = snapshotVerifierDefinition(workspace, command, trustedDeliverables);
659	  if (!current) return false;
660	  const stableEntries = (snapshot: Map<string, string>) =>
661	    [...snapshot].filter(([relative]) => !relative.startsWith("\0runtime-product-set:")).sort(([a], [b]) => a.localeCompare(b));
662	  const expectedEntries = stableEntries(expected);
663	  const currentEntries = stableEntries(current);
664	  if (currentEntries.length !== expectedEntries.length) return false;
665	  for (let index = 0; index < expectedEntries.length; index++) {
666	    const [expectedPath, expectedContent] = expectedEntries[index];
667	    const [currentPath, currentContent] = currentEntries[index];
668	    if (currentPath !== expectedPath || currentContent !== expectedContent) return false;
669	  }
670	  return true;
671	}
