673	/** TDD test files are deliberately excluded from ChangeBaseline.tests, so their bytes need a separate exact check. */
674	export function tddRedTestsMatchSnapshot(
675	  workspace: string,
676	  expected: Map<string, string>,
677	): boolean {
678	  const root = path.resolve(workspace);
679	  for (const [relative, content] of expected) {
680	    const absolute = path.resolve(root, relative);
681	    if (!absolute.startsWith(`${root}${path.sep}`)) return false;
682	    try {
683	      const stat = fs.lstatSync(absolute);
684	      const real = fs.realpathSync(absolute);
685	      if (stat.isSymbolicLink() || !real.startsWith(`${root}${path.sep}`) || !stat.isFile()) return false;
686	      if (fs.readFileSync(absolute, "utf8") !== content) return false;
687	    } catch {
688	      return false;
689	    }
690	  }
691	  return true;
692	}
