694	/** A new workspace-local npm dependency tree changes executable resolution after the baseline. */
695	export function npmDependencyBoundaryChangedSince(
696	  workspace: string,
697	  baseline: ChangeBaseline,
698	): boolean {
699	  if (!baseline.verifier) return true;
700	  const root = path.resolve(workspace);
701	  return [...baseline.verifier.keys()].some((key) => {
702	    if (!key.startsWith("\0must-remain-absent:")) return false;
703	    const relative = key.slice("\0must-remain-absent:".length);
704	    if (path.basename(relative) !== "node_modules") return false;
705	    return fs.existsSync(path.resolve(root, relative));
706	  });
707	}
