709	/** Whether any test file was added, removed or changed since the baseline. */
710	export function testsChangedSince(
711	  workspace: string,
712	  baseline: Map<string, string>,
713	): boolean {
714	  const now = snapshotTests(workspace);
715	  if (!now || now.size !== baseline.size) return true;
716	  for (const [file, content] of now)
717	    if (baseline.get(file) !== content) return true;
718	  return false;
719	}
