721	/** What a passing, deliverable-covering run of `command` shows, given the baseline (no extra run needed). */
722	export function judgeWithoutCopy(
723	  workspace: string,
724	  command: string,
725	  baseline: ChangeBaseline | null | undefined,
726	): Independence | "needs-copy" {
727	  if (!baseline || baseline.command !== command) {
728	    return {
729	      independent: false,
730	      detail: `no run of ${command} before this change was recorded, so nothing shows the tests exercise the change`,
731	    };
732	  }
733	  const verifierChanged = verifierDefinitionChangedSince(workspace, baseline);
734	  if (!baseline.verifier || baseline.verifier.size === 0) {
735	    return {
736	      independent: false,
737	      detail:
738	        "the pre-change verifier definition was not captured, so its test summary cannot establish independent evidence",
739	    };
740	  }
741	  const changed =
742	    !baseline.tests || testsChangedSince(workspace, baseline.tests);
743	  if (!baseline.failed) {
744	    return {
745	      independent: false,
746	      detail: changed
747	        ? "the existing tests passed before the change too; the new behaviour is checked only by tests Nexus wrote"
748	        : "the existing tests passed before the change too, so they do not show the change",
749	    };
750	  }
751	  if (npmDependencyBoundaryChangedSince(workspace, baseline)) {
752	    return {
753	      independent: false,
754	      detail:
755	        "a workspace-local npm dependency tree appeared after the baseline; its executable and package contents are not independently bound",
756	    };
757	  }
758	  if (!changed && !verifierChanged)
759	    return {
760	      independent: true,
761	      detail: "tests that failed before the change pass after it",
762	    };
763	  if (!baseline.tests)
764	    return {
765	      independent: false,
766	      detail:
767	        "Nexus changed test files that were too large to set aside, so its own test edits cannot be excluded",
768	    };
769	  return "needs-copy";
770	}
