772	const MAX_COPY_FILES = 20_000;
773	
774	/**
775	 * A copy of the workspace (dependency and build directories linked, not copied) with the test files as they were at
776	 * the baseline: tests the change added are removed, tests it edited are restored. Under `.nexus/verify/`, so it stays
777	 * inside the workspace's sandbox. Returns null when the workspace is too large to copy.
778	 */
779	export function prepareBaselineTestsCopy(
780	  workspace: string,
781	  tests: Map<string, string>,
782	  verifier: Map<string, string>,
783	): string | null {
784	  const root = path.resolve(workspace);
785	  const dir = path.join(root, ".nexus", "verify", randomUUID());
786	  let files = 0;
787	  const copy = (from: string, to: string): boolean => {
788	    fs.mkdirSync(to, { recursive: true });
789	    for (const entry of fs.readdirSync(from, { withFileTypes: true })) {
790	      const src = path.join(from, entry.name);
791	      const dst = path.join(to, entry.name);
792	      if (from === root && entry.name === ".nexus") continue;
793	      if (
794	        entry.isDirectory() &&
795	        SKIP_DIRS.has(entry.name) &&
796	        entry.name !== ".git"
797	      ) {
798	        fs.symlinkSync(src, dst, "dir");
799	      } else if (entry.isDirectory()) {
800	        if (entry.name === ".git") continue;
801	        if (!copy(src, dst)) return false;
802	      } else if (entry.isSymbolicLink()) {
803	        let realTarget: string;
804	        let targetIsDirectory: boolean;
805	        try {
806	          realTarget = fs.realpathSync(src);
807	          targetIsDirectory = fs.statSync(src).isDirectory();
808	        } catch {
809	          return false;
810	        }
811	        const relativeTarget = path.relative(root, realTarget);
812	        if (
813	          relativeTarget === ".." ||
814	          relativeTarget.startsWith(`..${path.sep}`) ||
815	          path.isAbsolute(relativeTarget)
816	        )
817	          return false;
818	        if (++files > MAX_COPY_FILES) return false;
819	        const linkTarget = fs.readlinkSync(src);
820	        const rebasedTarget = path.isAbsolute(linkTarget)
821	          ? path.join(dir, path.relative(root, realTarget))
822	          : linkTarget;
823	        fs.symlinkSync(rebasedTarget, dst, targetIsDirectory ? "dir" : "file");
824	      } else if (entry.isFile()) {
825	        if (++files > MAX_COPY_FILES) return false;
826	        fs.copyFileSync(src, dst);
827	      }
828	    }
829	    return true;
830	  };
831	  try {
832	    if (!copy(root, dir)) {
833	      fs.rmSync(dir, { recursive: true, force: true });
834	      return null;
835	    }
836	    for (const file of workspaceTestFiles(dir)) {
837	      if (!tests.has(path.relative(dir, file)))
838	        fs.rmSync(file, { force: true });
839	    }
840	    for (const [rel, content] of tests) {
841	      fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
842	      fs.writeFileSync(path.join(dir, rel), content);
843	    }
844	    for (const [rel, content] of verifier) {
845	    if (
846	      rel.startsWith("\0runtime-definition-set:") ||
847	      rel.startsWith("\0runtime-product-set:")
848	    ) continue;
849	      if (rel.startsWith("\0must-remain-absent:")) {
850	        const absent = rel.slice("\0must-remain-absent:".length);
851	        const destination = path.resolve(dir, absent);
852	        if (!destination.startsWith(dir + path.sep))
853	          throw new Error("verifier absence path escaped workspace");
854	        if (
855	          path.basename(absent) === "node_modules" &&
856	          fs.existsSync(destination)
857	        )
858	          throw new Error("mutable npm dependencies appeared after baseline");
859	        fs.rmSync(destination, { recursive: true, force: true });
860	        continue;
861	      }
862	      const destination = path.resolve(dir, rel);
863	      if (!destination.startsWith(`${dir}${path.sep}`))
864	        throw new Error("verifier path escaped workspace");
865	      fs.mkdirSync(path.dirname(destination), { recursive: true });
866	      fs.writeFileSync(destination, content);
867	    }
868	    return dir;
869	  } catch {
870	    fs.rmSync(dir, { recursive: true, force: true });
871	    return null;
872	  }
