82	  const skipped = (scope: string, extra: Partial<TypecheckEvidence> = {}) => ({
83	    evidence: (this.lastTypecheck = { status: "NOT_APPLICABLE" as const, scope, candidateId: opts.candidateId, ...extra, at: at() }),
84	  });
85	  if (mode === "off") return skipped("disabled by NEXUS_TYPECHECK / typecheck setting");
86	  const checks = discoverTypechecks(this.config.workspace);
87	  if (!checks.length) return skipped("no configured type-check project found");
88	  const enforced = mode === "enforce";
89	  const ledger = this.objective;
90	  const current = opts.current;
91	  // Modified = what an edit tool touched plus what the workspace diff shows changed since the task began (a shell
92	  // command, a formatter or a generator edits files no edit tool reported).
93	  const modified = new Set<string>(this.modifiedFiles);
94	  const shellChanged: string[] = [];
95	  try {
96	    for (const file of workspaceChangedPaths(this.config.workspace)) {
97	      if (modified.has(file) || this.preTaskChanged?.has(file)) continue;
98	      modified.add(file);
99	      shellChanged.push(path.relative(this.config.workspace, file));
100	    }
101	  } catch {}
102	  const results: TypecheckEvidence[] = [];
103	  const blockingMessages: string[] = [];
104	  const typecheckDeadline = Date.now() + Math.max(0, opts.budgetSecs) * 1000;
105	  for (const check of checks) {
106	    const named = { tool: check.tool, command: check.command, configPath: check.configPath, configSha256: check.configSha256, ...(check.toolSha256 ? { toolSha256: check.toolSha256 } : {}) };
107	    if (check.skipReason) {
108	      results.push({ status: check.discoveryIncomplete ? "UNAVAILABLE" : "NOT_APPLICABLE", ...named, enforced, scope: check.skipReason, candidateId: opts.candidateId, at: at() });
109	      if (enforced) blockingMessages.push(check.discoveryIncomplete
110	        ? `workspace type-check discovery was incomplete: ${check.skipReason}`
111	        : `${check.tool} type-check under ${check.configPath} was not run: ${check.skipReason}`);
112	      continue;
113	    }
114	    if (check.missingTool) {
115	      results.push({ status: "UNAVAILABLE", ...named, enforced, scope: `${check.tool} is not installed, so nothing was type-checked under ${check.configPath}`, candidateId: opts.candidateId, at: at() });
116	      if (enforced) blockingMessages.push(`${check.tool} type-check under ${check.configPath} is unavailable because ${check.tool} is not installed.`);
117	      continue;
118	    }
119	    const prior = ledger && current && enforced ? priorAttempt(ledger, check.command, current) : undefined;
120	    if (ledger && current && prior?.status === "FAILED" && (this.lastTypecheck?.command === check.command || this.lastTypecheck?.projects?.some((project: TypecheckEvidence) => project.command === check.command))) {
121	      recordAttempt(ledger, { command: check.command, ...current, status: "SKIPPED_UNCHANGED_INPUTS", ...(prior.failedCheck ? { failedCheck: prior.failedCheck } : {}) });
122	      results.push(this.lastTypecheck);
123	      blockingMessages.push(`${check.command} already failed on these exact inputs (attempt #${prior.n}).${prior.failedCheck ? ` Failed check: ${prior.failedCheck}` : ""}`);
124	      continue;
125	    }
126	    if (!(await this.ensureVerifierApproved(check.command, opts.onConfirm, "type-check for the task", check.toolSha256, enforced))) {
127	      const denied: TypecheckEvidence = { status: "NOT_APPLICABLE", ...named, enforced, scope: "type-check not approved", candidateId: opts.candidateId, at: at() };
128	      results.push(denied);
129	      if (enforced) blockingMessages.push(`type-check execution was not approved (${check.command})`);
130	      continue;
131	    }
132	    this.activity("verifying", { tool: check.command });
133	    const baseline = this.typecheckBaseline.get(check.command);
134	    const remainingSecs = Math.ceil((typecheckDeadline - Date.now()) / 1000);
135	    if (remainingSecs <= 0) {
136	      const timedOut: TypecheckEvidence = { status: "TIMED_OUT", enforced, ...named, scope: `not run: aggregate type-check budget of ${opts.budgetSecs}s exhausted`, candidateId: opts.candidateId, at: at() };
137	      results.push(timedOut);
138	      if (enforced) blockingMessages.push(`${check.tool} type-check under ${check.configPath} was not run because the aggregate ${opts.budgetSecs}s type-check budget was exhausted.`);
139	      continue;
140	    }
141	    const run = await runTypecheck(check, (command, timeout_secs) => this.bridge.executeTool("run_command", { command, timeout_secs }), this.config.workspace, modified, remainingSecs, baseline);
142	    // Without the pre-change signatures, PREEXISTING means only that the current compiler failed. On resume that
143	    // output cannot show whether the errors predate the task or were introduced by its edits, so never accept it as
144	    // an attributed baseline result.
145	    const resumedWithoutBaseline = this.typecheckBaselineUnavailableAfterResume && !baseline && run.status === "PREEXISTING";
146	    const resultStatus = resumedWithoutBaseline ? "UNAVAILABLE" : run.status;
147	    const resultScope = resumedWithoutBaseline
148	      ? "pre-change type-check baseline is unavailable after resume; current diagnostics cannot be attributed"
149	      : `under ${check.configPath}`;
150	    const excerpt = `(untrusted compiler output)\n${safeTerminal(foldVoluminousOutput(run.output || "", 30, 2000))}`;
151	    const evidence: TypecheckEvidence = {
152	      status: resultStatus, enforced, ...named,
153	      ...(run.version ? { toolVersion: run.version } : {}),
154	      exitCode: run.exitCode,
155	      ...(run.errorCount !== undefined ? { errorCount: run.errorCount, firstDiagnostics: (run.firstDiagnostics ?? []).map((d) => safeTerminal(d)) } : {}),
156	      ...(baseline ? { baselineErrorCount: baseline.size } : {}),
157	      ...(run.introducedCount !== undefined ? { introducedCount: run.introducedCount } : {}),
158	      ...(shellChanged.length ? { shellChangedFiles: shellChanged.slice(0, 20) } : {}),
159	      scope: resultScope,
160	      ...(run.status === "PASSED" ? {} : { excerpt }), candidateId: opts.candidateId, at: at(),
161	    };
162	    results.push(evidence);
163	    const failedOrTimedOut = run.status === "FAILED" || run.status === "TIMED_OUT";
164	    const blocking = failedOrTimedOut || resumedWithoutBaseline;
165	    if (ledger && current && (failedOrTimedOut || run.status === "PASSED")) recordAttempt(ledger, {
166	      command: check.command, ...current, mutationSeq: this.mutationSeq,
167	      status: run.status === "PASSED" ? "PASSED" : run.status === "TIMED_OUT" ? "TIMED_OUT" : "FAILED",
168	      ...(failedOrTimedOut ? {
169	        failedCheck: safeTerminal(run.firstDiagnostics?.[0] ?? run.status).slice(0, 240),
170	        ...attemptEvidence(run.output, run.exitCode, { timedOut: run.status === "TIMED_OUT" }),
171	        ...(run.status === "FAILED" ? { classification: "CANDIDATE_FAILED" as const, failingTests: (run.firstDiagnostics ?? []).map((d) => safeTerminal(d).slice(0, 240)) } : {}),
172	      } : {}),
173	    });
174	    if (enforced && blocking) {
175	      const what = resumedWithoutBaseline
176	        ? "could not be attributed because its pre-change baseline was not retained across resume"
177	        : run.status === "FAILED" ? "failed" : `timed out after ${opts.budgetSecs}s`;
178	      blockingMessages.push(`${check.tool} type-check ${what} under ${check.configPath} (sha256 ${check.configSha256.slice(0, 12)}). Command: ${check.command}\n${excerpt}`);
179	    }
180	  }
181	  const priority: TypecheckEvidence["status"][] = ["FAILED", "TIMED_OUT", "UNAVAILABLE", "NOT_APPLICABLE", "ENVIRONMENT", "PREEXISTING", "PASSED"];
182	  const primary = priority.map((status) => results.find((item) => item.status === status)).find((item) => item !== undefined) ?? results[0];
183	  const evidence: TypecheckEvidence = { ...primary, scope: results.length === 1 ? primary.scope : `${results.length} project check(s)`, projects: results };
184	  this.lastTypecheck = evidence;
185	  return { evidence, ...(blockingMessages.length ? { block: `Verification Oracle: tests passed, but a mandatory project type-check did not complete successfully; changes are NOT verified.\n${blockingMessages.join("\n\n") }\nFix the type errors or resolve the unavailable approval, then call task_completed again.` } : {}) };
186	}
