188	export async function captureChangeBaselineImpl(this: any, confirmHandler?: ConfirmHandler): Promise<void> {
189	  // What was already changed when the task began (carried changes included), so only later shell changes are the candidate's.
190	  if (!this.preTaskChanged) {
191	    try {
192	      this.preTaskChanged = new Set(workspaceChangedPaths(this.config.workspace));
193	    } catch {}
194	  }
195	  // A new conversation does not make candidate writes from an interrupted or
196	  // resumed task trustworthy. Do not establish a discovered-verifier baseline
197	  // from a workspace that still carries an unverified-change obligation.
198	  if (this.hasPendingModifications || this.verificationBaselineInvalidated || this.changeBaseline !== undefined || this.config.dryRun || this.isReadOnly()) return;
199	  const configured = this.config.authoritativeVerifierCommand?.trim();
200	  const command = configured || discoverVerifier(this.config.workspace)?.command;
201	  if (!command) {
202	    this.changeBaseline = null;
203	    return;
204	  }
205	  this.judgeReceiptBaselineOnce(); // see the field: verification proceeds, no receipt is issued
206	  try {
207	    const tests = snapshotTests(this.config.workspace);
208	    const trustedDeliverables = [...(this.config.trustedDeliverableFiles ?? [])];
209	    const definition = this.verifierDefinitionAtCapture(command, trustedDeliverables);
210	    if (configured) {
211	      this.changeBaseline = { command, failed: false, tests, ...definition, trustedDeliverables, at: new Date().toISOString() };
212	      if (this.durable) {
213	        try {
214	          this.checkpointDurableState("configured verifier baseline captured");
215	        } catch (err: any) {
216	          this.reportPersistenceFailure("baseline", err);
217	        }
218	      }
219	      return;
220	    }
221	    const approved = await this.ensureVerifierApproved(command, confirmHandler, undefined, undefined, false);
222	    if (!approved) {
223	      this.changeBaseline = null;
224	      return;
225	    }
226	    this.activity("verifying", { tool: `${command} (before the change)` });
227	    const deadlineSecs = this.config.verifierTimeoutSecs ?? DEFAULT_VERIFIER_TIMEOUT_SECS;
228	    const run = await runTestSuiteWithExecutor(this.config.workspace, (c) => this.bridge.executeTool("run_command", { command: c, timeout_secs: deadlineSecs }), command);
229	    this.changeBaseline = { command, failed: !run.success, tests, ...definition, trustedDeliverables, at: new Date().toISOString() };
230	    this.turnVerifierRuns.push({ command, phase: "before_change", passed: run.success });
231	    await captureTypecheckBaselineImpl.call(this, confirmHandler, deadlineSecs);
232	    if (this.durable) {
233	      try {
234	        this.checkpointDurableState("baseline captured");
235	      } catch (err: any) {
236	        this.reportPersistenceFailure("baseline", err);
237	      }
238	    }
239	  } catch {
240	    this.changeBaseline = null;
241	  }
242	}
243	
244	export function verifierDefinitionAtCaptureImpl(this: any, command: string, trustedDeliverables: readonly string[]): Pick<ChangeBaseline, "verifier" | "verifierUnbindableReason"> {
245	  const definition = snapshotVerifierDefinitionWithReason(this.config.workspace, command, trustedDeliverables);
246	  return definition.verifier || isInlineProgramVerifier(command) ? { verifier: definition.verifier } : { verifier: null, verifierUnbindableReason: definition.reason };
247	}
248	
249	export async function judgeIndependenceImpl(this: any, command: string, deadlineSecs: number, confirmHandler?: ConfirmHandler): Promise<Independence> {
250	  const judged = judgeWithoutCopy(this.config.workspace, command, this.changeBaseline);
251	  if (judged !== "needs-copy") return judged;
252	  const approved = await this.ensureVerifierApproved(command, confirmHandler);
253	  if (!approved) return { independent: false, detail: "verifier execution was not approved" };
254	  // Nexus edited test files: run the tests as they were before the change against the changed code.
255	  const dir = prepareBaselineTestsCopy(this.config.workspace, this.changeBaseline!.tests!, this.changeBaseline!.verifier!);
256	  if (!dir) return { independent: false, detail: "the workspace is too large to rerun the pre-change tests without Nexus's own test edits" };
257	  try {
258	    this.activity("verifying", { tool: `${command} (tests as they were before the change)` });
259	    const quoted = `'${dir.replace(/'/g, `'\\''`)}'`;
260	    const run = await runTestSuiteWithExecutor(this.config.workspace, (c) => this.bridge.executeTool("run_command", { command: `cd ${quoted} && ${c}`, timeout_secs: deadlineSecs }), command);
261	    return run.success && hasExecutedTests(run.rawOutput || "")
262	      ? { independent: true, detail: "tests that failed before the change pass after it, with Nexus's own test edits set aside" }
263	      : { independent: false, detail: "it passes only with tests Nexus wrote or edited; the tests as they were before the change still fail" };
264	  } finally {
265	    fs.rmSync(dir, { recursive: true, force: true });
266	  }
267	}
268	
269	export async function runRequirementVerifierImpl(this: any, requirement: { id: string; verifierSource?: string }, command: string): Promise<string | undefined> {
270	  const ledger = this.objective;
271	  const state = this.verifierState();
272	  if (!ledger || !state || priorAttempt(ledger, command, state, requirement.id)) return undefined;
273	  const onConfirm = this.activeTurn?.onConfirm;
274	  const origin = `${requirement.verifierSource === "operator" ? "operator-declared" : "model-declared"} verifier for ${requirement.id}: ${command}`;
275	  if (!(await this.ensureVerifierApproved(command, onConfirm, origin))) {
276	    return `${requirement.id}: verifier execution was not approved${onConfirm ? "" : " (it requires operator approval and no operator is present)"}`;
277	  }
278	  const deadlineSecs = this.config.verifierTimeoutSecs ?? DEFAULT_VERIFIER_TIMEOUT_SECS;
279	  this.activity("verifying", { tool: command });
280	  const run = await runTestSuiteWithExecutor(this.config.workspace, (c) => this.bridge.executeTool("run_command", { command: c, timeout_secs: deadlineSecs }), command);
281	  // The state after the run: a verifier that writes build output must still be able to verify what it produced.
282	  const after = this.verifierState();
283	  if (after) {
284	    recordAttempt(ledger, {
285	      command,
286	      ...after,
287	      status: run.success ? "PASSED" : run.timedOut ? "TIMED_OUT" : "FAILED",
288	      requirementId: requirement.id,
289	      ...(run.success ? {} : { failedCheck: failedCheckFrom(run.rawOutput || ""), ...attemptEvidence(run.rawOutput || "", run.exitCode, { timedOut: run.timedOut, executorFailed: run.executorFailed }) }),
290	    });
291	  }
292	  this.turnVerifierRuns.push({ command, phase: "completion", passed: run.success });
293	  return undefined;
294	}
295	
296	
297	/**
298	 * VC-6: the type-check errors that exist before the change, so an error that appears in an untouched file (a caller the
299	 * change broke) is told apart from one that was already there. This includes Cargo: its per-workspace target directory
300	 * is reused by the completion check, so the baseline's dependency build is reused rather than repeated. Nothing is
301	 * recorded when the tool is missing, the run is not approved,
302	 * times out or cannot be attributed; completion then behaves as before.
303	 */
304	export async function captureTypecheckBaselineImpl(this: any, confirmHandler: ConfirmHandler | undefined, deadlineSecs: number): Promise<void> {
305	  try {
306	    if (typecheckMode(this.config.typecheck, Boolean(this.config.authoritativeVerifierCommand?.trim())) === "off") return;
307	    for (const check of discoverTypechecks(this.config.workspace)) {
308	      if (check.skipReason || check.missingTool) continue;
309	      if (!(await this.ensureVerifierApproved(check.command, confirmHandler, "type-check baseline (before the change)", check.toolSha256, false))) continue;
310	      this.activity("verifying", { tool: `${check.command} (before the change)` });
311	      const run = await runTypecheck(check, (command, timeout_secs) => this.bridge.executeTool("run_command", { command, timeout_secs }), this.config.workspace, new Set(), deadlineSecs);
312	      if (run.status === "PASSED") this.typecheckBaseline.set(check.command, new Set());
313	      else if (run.status === "PREEXISTING") this.typecheckBaseline.set(check.command, new Set(run.signatures ?? []));
314	    }
315	  } catch {}
316	}

