1535	    return deepFreezeTurn(assertTurnResultInvariants({ ...base, execution: "COMPLETED", outcome: "UNVERIFIED", reason: "VERIFICATION_NOT_RUN" }));
1536	  }
1537	  // The operator's verifier refused this turn's completion and the turn ended anyway (e.g. with a final answer).
1538	  if (this.turnConfiguredVerifier === "FAILED" && (evidence?.status === "FAILED" || evidence?.status === "TIMED_OUT")) {
1539	    return deepFreezeTurn(assertTurnResultInvariants({
1540	      ...base, execution: "COMPLETED", outcome: "NOT_ESTABLISHED",
1541	      reason: evidence.status === "FAILED" ? "VERIFIER_FAILED" : "VERIFIER_TIMED_OUT", detail: evidence.command,
1542	    }));
1543	  }
1544	  // The operator's verifier must pass before any completion; a turn that ended without it passing (a final answer
1545	  // without task_completed, or a dry-run or read-only turn, which never runs it) is not verified.
1546	  if (this.configuredVerifierGatesCompletion() && this.turnConfiguredVerifier !== "PASSED") {
1547	    return deepFreezeTurn(assertTurnResultInvariants({ ...base, execution: "COMPLETED", outcome: "UNVERIFIED", reason: "VERIFICATION_NOT_RUN" }));
1548	  }
1549	  // No verifier backs a read-only result, so it rests on the observations the model saw. If compaction removed some
1550	  // and the model never re-read them, the result may be recalled rather than observed: it is not established.
1551	  if (this.turnRemovedObservations.size > 0) return contextEvidenceLost();
1552	  return deepFreezeTurn(assertTurnResultInvariants({ ...base, execution: "COMPLETED", outcome: "NOT_REQUIRED" }));
