188	export async function captureChangeBaselineImpl(this: any, confirmHandler?: ConfirmHandler): Promise<void> {
189	  // What was already changed when the task began (carried changes included), so only later shell changes are the candidate's.
190	  if (!this.preTaskChanged) {
191	    try {
192	      this.preTaskChanged = new Set(workspaceChangedPaths(this.config.workspace));
193	    } catch {}
194	  }
195	  // A new conversation does not make candidate writes from an interrupted or
196	  // resumed task trustworthy. Do not establish a discovered-verifier baseline
197	  // from a workspace that still carries an unverified-change obligation.
198	  if (this.hasPendingModifications || this.verificationBaselineInvalidated || this.changeBaseline !== undefined || this.config.dryRun || this.isReadOnly()) return;
199	  const configured = this.config.authoritativeVerifierCommand?.trim();
200	  const command = configured || discoverVerifier(this.config.workspace)?.command;
201	  if (!command) {
202	    this.changeBaseline = null;
203	    return;
204	  }
205	  this.judgeReceiptBaselineOnce(); // see the field: verification proceeds, no receipt is issued
206	  try {
207	    const tests = snapshotTests(this.config.workspace);
208	    const trustedDeliverables = [...(this.config.trustedDeliverableFiles ?? [])];
209	    const definition = this.verifierDefinitionAtCapture(command, trustedDeliverables);
210	    if (configured) {
211	      this.changeBaseline = { command, failed: false, tests, ...definition, trustedDeliverables, at: new Date().toISOString() };
212	      if (this.durable) {
213	        try {
214	          this.checkpointDurableState("configured verifier baseline captured");
215	        } catch (err: any) {
216	          this.reportPersistenceFailure("baseline", err);
217	        }
218	      }
219	      return;
220	    }
221	    const approved = await this.ensureVerifierApproved(command, confirmHandler, undefined, undefined, false);
222	    if (!approved) {
223	      this.changeBaseline = null;
224	      return;
225	    }
226	    this.activity("verifying", { tool: `${command} (before the change)` });
227	    const deadlineSecs = this.config.verifierTimeoutSecs ?? DEFAULT_VERIFIER_TIMEOUT_SECS;
228	    const run = await runTestSuiteWithExecutor(this.config.workspace, (c) => this.bridge.executeTool("run_command", { command: c, timeout_secs: deadlineSecs }), command);
229	    this.changeBaseline = { command, failed: !run.success, tests, ...definition, trustedDeliverables, at: new Date().toISOString() };
230	    this.turnVerifierRuns.push({ command, phase: "before_change", passed: run.success });
231	    await captureTypecheckBaselineImpl.call(this, confirmHandler, deadlineSecs);
232	    if (this.durable) {
233	      try {
234	        this.checkpointDurableState("baseline captured");
235	      } catch (err: any) {
236	        this.reportPersistenceFailure("baseline", err);
237	      }
238	    }
239	  } catch {
240	    this.changeBaseline = null;
241	  }
242	}
