      if (token === "--") return tokens.slice(i + 1).some((t) => !t.startsWith("-"));
      if (takesValue.has(token)) {
        i++;
        continue;
      }
      if (token.startsWith("-") || /[;&|]/.test(token)) {
        if (/[;&|]/.test(token)) break;
        continue;
      }
      return true;
