35	/**
36	 * Host-side Git must not run in a worktree whose `.git` (or a nested repository) the sandboxed agent could have planted.
37	 * Returns the `--git-dir`/`--work-tree` pair to run Git against (empty for a plain repository), so a pointer rewritten
38	 * after this check is not re-read.
39	 */
40	export function trustedGitArgs(workspace: string): string[] {
41	  const checkout = verifyCheckout(workspace);
42	  const reason = checkout.reason ?? (checkout.gitDir ? nestedRepositoryReason(workspace) : undefined); // and any repository planted below it
43	  if (reason) throw new UntrustedCheckoutError(workspace, reason, []);
44	  return checkout.gitDir ? ["--git-dir", checkout.gitDir, "--work-tree", checkout.workTree!] : [];
45	}
46	
47	/** `git status` in `format` for the workspace's repository, without Nexus state. Throws when git fails. */
48	export function workspaceStatus(workspace: string, format: "--porcelain" | "--short", pin: string[] = trustedGitArgs(workspace)): string {
49	  return execFileSync("git", [...pin, "status", format, ...WITHOUT_NEXUS_STATE], {
50	    cwd: workspace,
51	    env: pathspecEnv(),
52	    encoding: "utf-8",
53	    stdio: ["ignore", "pipe", "pipe"],
54	    maxBuffer: 64 * 1024 * 1024,
55	  });
56	}
57	
58	/**
59	 * Absolute paths the workspace's repository reports as changed (modified, added, deleted, renamed, untracked), whoever
60	 * changed them: an edit tool, a shell command or a formatter. Throws when git fails (not a repository, refused checkout).
61	 */
62	export function workspaceChangedPaths(workspace: string): string[] {
63	  const out = execFileSync("git", [...trustedGitArgs(workspace), "-c", "core.quotepath=off", "status", "--porcelain=v1", "-z", "--untracked-files=all", ...WITHOUT_NEXUS_STATE], {
64	    cwd: workspace,
65	    env: pathspecEnv(),
66	    encoding: "utf-8",
67	    stdio: ["ignore", "pipe", "pipe"],
68	    maxBuffer: 64 * 1024 * 1024,
69	  });
70	  const top = execFileSync("git", [...trustedGitArgs(workspace), "rev-parse", "--show-toplevel"], { cwd: workspace, encoding: "utf-8", stdio: ["ignore", "pipe", "ignore"] }).trim();
71	  const records = out.split("\0").filter(Boolean);
72	  const paths: string[] = [];
73	  for (let i = 0; i < records.length; i++) {
74	    const rec = records[i];
75	    paths.push(path.resolve(top, rec.slice(3)));
76	    // A rename or copy is followed by its source path as a separate record.
77	    if (rec[0] === "R" || rec[0] === "C") i++;
78	  }
79	  return paths;
80	}
81	
82	/** The current branch; on an unborn branch (no commit yet) `rev-parse` fails, so read the symbolic ref instead. */
83	function currentBranch(workspace: string, pin: string[]): string {
84	  const run = (args: string[]) =>
85	    execFileSync("git", [...pin, ...args], { cwd: workspace, encoding: "utf-8", stdio: ["ignore", "pipe", "ignore"] }).trim();
86	  try {
87	    return run(["rev-parse", "--abbrev-ref", "HEAD"]);
88	  } catch {
89	    return run(["symbolic-ref", "--short", "HEAD"]);
90	  }
91	}
