1	/**
2	 * PF-2: the machine contract of `nexus run`: the versioned JSON document `--json` prints (docs/protocol/run-result-v1.schema.json,
3	 * generated from src/run_contract.ts), the exit-code table (the same in code and in docs/USER_MANUAL.md), and the task
4	 * read from `--input-json` or stdin. The consumer tests spawn the real CLI against a scripted gateway.
5	 */
6	import "./helpers/leak_guard.js";
7	import { test } from "node:test";
8	import assert from "node:assert/strict";
9	import fs from "node:fs";
10	import os from "node:os";
11	import path from "node:path";
12	import { spawn } from "node:child_process";
13	import { Readable } from "node:stream";
14	import { fileURLToPath } from "node:url";
15	import { ApplicationCore } from "../src/core/app.js";
16	import { exitCodeForTurn, type TurnResult } from "../src/core/turn.js";
17	import {
18	  RUN_EXIT_CODES, RUN_EXIT_FOR_COMPLETED_OUTCOME, RUN_EXIT_FOR_EXECUTION, RUN_INPUT_MAX_BYTES, RUN_INPUT_SCHEMA_VERSION, RUN_RESULT_SCHEMA_VERSION,
19	  parseRunInput, resolveRunTask, runExitCode, runExitNameForTurn, runJsonResult, type RunExitName,
20	} from "../src/run_contract.js";
21	import { sha256 } from "../scripts/gen_protocol_schema.mjs";
22	import { generateRunResultSchema, runResultLedgerProblem, runResultSchemaFile, RUN_RESULT_LEDGER_FILE } from "../scripts/gen_run_result_schema.mjs";
23	import { validate, type Schema } from "./helpers/json_schema.js";
24	import { startGateway, makeRepo, makeHome, type Reply } from "./helpers/fixtures.js";
25	import { mute } from "./helpers/capacity_fixture.js";
26	
27	const CLI_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
28	const MANUAL = path.resolve(CLI_DIR, "..", "docs", "USER_MANUAL.md");
29	const checkedIn = fs.readFileSync(runResultSchemaFile(RUN_RESULT_SCHEMA_VERSION), "utf8");
30	const schema: Schema = JSON.parse(checkedIn);
31	const errorsOf = (doc: unknown, branch?: "RunJsonResult" | "RunJsonError") => validate(doc, branch ? { $ref: `#/$defs/${branch}` } : schema, schema);
32	
33	// ---- The document built from a real runTask ----
34	// This test is the first in the file on purpose: runTask captures process.stdout while it runs (with `json` or `quiet`),
35	// and node:test reports through the same stdout, so the reports of tests that finished just before it would be lost.
36	
37	test("the document built from a real runTask validates, has schema_version first and round-trips through JSON", async () => {
38	  const savedHome = process.env.HOME;
39	  const home = makeHome();
40	  process.env.HOME = home;
41	  const gateway = await startGateway(() => ({ kind: "text", content: "the answer" }));
42	  const repo = makeRepo();
43	  const app = new ApplicationCore({ endpoint: gateway.url, model: "m", maxSteps: 3, temperature: 0, workspace: repo, shell: "bash" } as any);
44	  mute(app.getAgent());
45	  try {
46	    const result = await app.runTask("answer briefly", { quiet: true });
47	    const doc = runJsonResult(result);
48	    assert.equal(Object.keys(doc)[0], "schema_version");
49	    assert.equal(doc.schema_version, RUN_RESULT_SCHEMA_VERSION);
50	    assert.equal("cloudUsage" in doc, false, "no cloud request, no cloudUsage");
51	    // Every result member is carried unchanged.
52	    const { schema_version: _version, ...rest } = doc;
53	    assert.deepEqual(rest, result);
54	    const text = JSON.stringify(doc);
55	    const parsed = JSON.parse(text);
56	    assert.equal(Object.keys(parsed)[0], "schema_version");
57	    assert.deepEqual(errorsOf(parsed), []);
58	    assert.deepEqual(errorsOf(parsed, "RunJsonResult"), []);
59	    assert.equal(JSON.stringify(parsed), text, "round trip");
60	    assert.equal(parsed.output, "the answer");
61	    assert.equal(parsed.exitCode, runExitCode(runExitNameForTurn(parsed.turn)));
62	
63	    const totals = { requests: 1, inputTokens: 2, outputTokens: 3, costUsd: 0, unpricedRequests: 0, uncertainRequests: 0, estimatedRequests: 0, cachedTokens: 0, cacheReportedPromptTokens: 0 };
64	    const withCloud = JSON.parse(JSON.stringify(runJsonResult(result, totals)));
65	    assert.deepEqual(withCloud.cloudUsage, totals);
66	    assert.deepEqual(errorsOf(withCloud, "RunJsonResult"), []);
67	    assert.equal("cloudUsage" in runJsonResult(result, { ...totals, requests: 0 }), false);
68	
69	    // The schema rejects what a consumer must be able to rely on.
70	    assert.ok(errorsOf({ ...parsed, schema_version: 2 }).length > 0);
71	    const { schema_version: _dropped, ...unversioned } = parsed;
72	    assert.ok(errorsOf(unversioned).some((error) => /missing required schema_version/.test(error)));
73	    assert.ok(errorsOf({ ...parsed, exitCode: "0" }, "RunJsonResult").some((error) => /\$\.exitCode: expected number/.test(error)));
74	    assert.deepEqual(errorsOf({ ...parsed, added_later: true }), [], "a member added later is ignored");
75	  } finally {
76	    app.shutdown();
77	    await gateway.close();
78	    process.env.HOME = savedHome;
79	    fs.rmSync(repo, { recursive: true, force: true });
80	    fs.rmSync(home, { recursive: true, force: true });
81	  }
82	});
83	
84	// ---- Schema, ledger and exit-code table ----
85	
86	test("the checked-in run-result schema equals a fresh generation from src/run_contract.ts", () => {
87	  const generated = generateRunResultSchema();
88	  assert.equal(generated.version, RUN_RESULT_SCHEMA_VERSION);
89	  assert.equal(
90	    checkedIn,
91	    generated.text,
92	    "docs/protocol/run-result schema is out of date: run `node cli/scripts/gen_run_result_schema.mjs`, then record the version decision in docs/protocol/RUN_RESULT_VERSIONS.json",
93	  );
94	});
95	
96	test("the newest run-result ledger entry records the current schema and schema_version", () => {
97	  const ledger = JSON.parse(fs.readFileSync(RUN_RESULT_LEDGER_FILE, "utf8"));
98	  assert.equal(runResultLedgerProblem(checkedIn, ledger, RUN_RESULT_SCHEMA_VERSION), undefined);
99	  for (const entry of ledger) {
100	    assert.ok(Number.isInteger(entry.schema_version) && /^[0-9a-f]{64}$/.test(entry.schemaSha256) && typeof entry.note === "string" && entry.note.trim(), "each entry has schema_version, schemaSha256 and a note");
101	  }
102	  // The rule itself: a changed schema, or a version bump, without a new entry is a failure.
103	  assert.match(runResultLedgerProblem(`${checkedIn} `, ledger, RUN_RESULT_SCHEMA_VERSION) ?? "", /add an entry/);
104	  assert.match(runResultLedgerProblem(checkedIn, ledger, RUN_RESULT_SCHEMA_VERSION + 1) ?? "", /RUN_RESULT_SCHEMA_VERSION is/);
105	  assert.match(runResultLedgerProblem(checkedIn, [], RUN_RESULT_SCHEMA_VERSION) ?? "", /no entries/);
106	  assert.equal(ledger[ledger.length - 1].schemaSha256, sha256(checkedIn));
107	});
108	
109	test("the schema is a union of a result and an error document, both open and both carrying schema_version", () => {
110	  assert.equal(schema.$schema, "https://json-schema.org/draft/2020-12/schema");
111	  assert.deepEqual(schema.$defs.RunJsonOutput.anyOf, [{ $ref: "#/$defs/RunJsonError" }, { $ref: "#/$defs/RunJsonResult" }]);
112	  for (const name of ["RunJsonResult", "RunJsonError"]) {
113	    const branch = schema.$defs[name];
114	    assert.equal(branch.properties.schema_version.const, RUN_RESULT_SCHEMA_VERSION);
115	    assert.ok(branch.required.includes("schema_version"));
116	    assert.notEqual(branch.additionalProperties, false, "the document stays open to members added later");
117	  }
118	  // What tells the two apart: only a result has `turn` and `exitCode`.
119	  assert.ok(schema.$defs.RunJsonResult.required.includes("turn") && schema.$defs.RunJsonResult.required.includes("exitCode"));
120	  assert.ok(!("turn" in schema.$defs.RunJsonError.properties) && !("exitCode" in schema.$defs.RunJsonError.properties));
121	});
122	
123	test("the exit-code table gives every turn ending the code exitCodeForTurn computes", () => {
124	  // The states and outcomes come from the published schema (so from the types): a new one fails here until its row is decided.
125	  const executions: string[] = schema.$defs.ExecutionState.enum;
126	  const outcomes: string[] = schema.$defs.EngineeringOutcome.enum;
127	  assert.deepEqual([...Object.keys(RUN_EXIT_FOR_EXECUTION), "COMPLETED"].sort(), [...executions].sort());
128	  assert.deepEqual(Object.keys(RUN_EXIT_FOR_COMPLETED_OUTCOME).sort(), [...outcomes].sort());
129	  for (const execution of executions) {
130	    for (const outcome of outcomes) {
131	      const turn = { execution, outcome } as TurnResult;
132	      assert.equal(exitCodeForTurn(turn), runExitCode(runExitNameForTurn(turn)), `${execution}/${outcome}`);
133	    }
134	  }
135	  assert.equal(new Set(RUN_EXIT_CODES.map((row) => row.name)).size, RUN_EXIT_CODES.length, "row names are unique");
136	  assert.deepEqual([...new Set(RUN_EXIT_CODES.map((row) => row.code))], [0, 1, 2, 130], "no code was added or changed");
137	  assert.deepEqual([runExitCode("ok"), runExitCode("failed"), runExitCode("unverified"), runExitCode("usage"), runExitCode("interrupted")], [0, 1, 2, 2, 130]);
138	});
139	
140	test("the manual's exit-code table is the exported table", () => {
141	  const manual = fs.readFileSync(MANUAL, "utf8");
142	  const start = manual.indexOf("### Exit codes of `nexus run`");
143	  assert.ok(start >= 0, "the manual has the section");
144	  const rows = manual.slice(start).split("\n").slice(1);
145	  const first = rows.findIndex((line) => line.startsWith("|"));
146	  const table: string[] = [];
147	  for (let i = first; i < rows.length && rows[i].startsWith("|"); i++) table.push(rows[i]);
148	  const cells = table.map((line) => line.split("|").slice(1, -1).map((cell) => cell.trim()));
149	  assert.deepEqual(cells[0], ["Code", "Name", "When"]);
150	  assert.match(cells[1].join(""), /^[-: ]+$/);
151	  assert.deepEqual(
152	    cells.slice(2).map(([code, name, when]) => ({ code: Number(code), name: name.replace(/`/g, ""), when })),
153	    RUN_EXIT_CODES.map((row) => ({ ...row })),
154	  );
155	});
156	
157	// ---- Consumer: the real CLI ----
158	
159	interface CliRun { code: number | null; stdout: string; stderr: string }
160	
161	/** Runs `nexus run <args>` (the source entry) with a throwaway HOME and no operator environment. `stdin`: text piped in and closed. */
162	function runCli(home: string, args: string[], stdin?: string): Promise<CliRun> {
163	  const env = { ...process.env };
164	  for (const key of Object.keys(env)) if (/^(LOCAL_LLM_|LOCAL_HARNESS_|NEXUS_)/.test(key)) delete env[key];
165	  return new Promise((resolve, reject) => {
166	    const child = spawn(process.execPath, ["--import", "tsx", "src/index.ts", "run", ...args], {
167	      cwd: CLI_DIR,
168	      env: { ...env, HOME: home, XDG_CONFIG_HOME: path.join(home, ".config"), XDG_DATA_HOME: path.join(home, ".local", "share"), XDG_STATE_HOME: path.join(home, ".local", "state"), XDG_CACHE_HOME: path.join(home, ".cache") },
169	      stdio: [stdin === undefined ? "ignore" : "pipe", "pipe", "pipe"],
170	    });
171	    let stdout = "";
172	    let stderr = "";
173	    child.stdout!.on("data", (chunk) => (stdout += chunk));
174	    child.stderr!.on("data", (chunk) => (stderr += chunk));
175	    child.on("error", reject);
176	    child.on("close", (code) => resolve({ code, stdout, stderr }));
177	    if (stdin !== undefined) {
178	      child.stdin!.on("error", () => {}); // the child may exit (a usage error) before taking all of it
179	      child.stdin!.end(stdin);
180	    }
181	  });
182	}
