186	/** One CLI run against a scripted gateway in a fresh repository and HOME; `check` runs before they are removed. */
187	async function scenario<T>(s: Scenario, check: (run: CliRun, at: { repo: string; requests: number }) => T): Promise<T> {
188	  const gateway = await startGateway(s.script);
