184	interface Scenario { script: (n: number) => Reply; files?: Record<string, string>; args: (repo: string, home: string) => string[]; stdin?: string }
185	
186	/** One CLI run against a scripted gateway in a fresh repository and HOME; `check` runs before they are removed. */
187	async function scenario<T>(s: Scenario, check: (run: CliRun, at: { repo: string; requests: number }) => T): Promise<T> {
188	  const gateway = await startGateway(s.script);
189	  const repo = makeRepo(s.files ?? {});
190	  const home = makeHome();
191	  try {
192	    const run = await runCli(home, ["-e", gateway.url, "-m", "m", "-w", repo, ...s.args(repo, home)], s.stdin);
193	    return check(run, { repo, requests: gateway.requests.length });
194	  } finally {
195	    await gateway.close();
196	    fs.rmSync(repo, { recursive: true, force: true });
197	    fs.rmSync(home, { recursive: true, force: true });
198	  }
199	}
