201	/** What a consumer does: stdout is exactly one JSON document, valid against the published schema. */
202	function consume(run: CliRun): any {
203	  let doc: any;
204	  try {
205	    doc = JSON.parse(run.stdout);
206	  } catch {
207	    assert.fail(`stdout is not one JSON document: ${run.stdout.slice(0, 200)}\nstderr: ${run.stderr.slice(0, 400)}`);
208	  }
209	  assert.equal(run.stdout, `${JSON.stringify(doc, null, 2)}\n`, "nothing but the document on stdout");
210	  assert.equal(Object.keys(doc)[0], "schema_version");
211	  assert.equal(doc.schema_version, RUN_RESULT_SCHEMA_VERSION);
212	  assert.deepEqual(errorsOf(doc), []);
213	  return doc;
214	}
