216	/** A finished task: the result branch, and the process exit code is the table's code for the turn's ending. */
217	function consumeResult(run: CliRun, expected: RunExitName): any {
218	  const doc = consume(run);
219	  assert.deepEqual(errorsOf(doc, "RunJsonResult"), []);
220	  assert.equal(runExitNameForTurn(doc.turn), expected, `${doc.turn.execution}/${doc.turn.outcome}: ${doc.turn.reason}`);
221	  assert.equal(run.code, runExitCode(expected));
222	  assert.equal(doc.exitCode, run.code, "exitCode repeats the process exit code");
223	  assert.equal(doc.success, run.code === 0);
224	  return doc;
225	}
