program
  .command("run")
  .description("Run an autonomous coding task")
  .argument("[prompt...]", "The coding instructions / task prompt")
  .option("-e, --endpoint <url>", "Local LLM endpoint (default: http://localhost:1234/v1 or $LOCAL_LLM_ENDPOINT)")
  .option("-m, --model <name>", "Model name identifier (default: active model in LM Studio/vLLM)")
  .option("-w, --workspace <path>", "Workspace directory to inspect and modify (default: current directory)")
  .option("-s, --max-steps <number>", "Steps per segment; continuation checkpoints there instead of stopping", "30")
  .option("--max-total-steps <number>", "Continuation: objective-wide step limit shared across resumes (default: 500)")
  .option("--max-tool-invocations <number>", "Objective-wide tool dispatch limit shared across resumes (default: 1000; also NEXUS_MAX_TOOL_INVOCATIONS)")
  .option("--strict-token-count", "Refuse a request the connection could not count on a worker (default: proceed on the labelled estimate)")
  .option("--max-turn-minutes <number>", "Continuation: active invocation wall-clock limit in minutes (default: 480)")
  .option("--stagnation-steps <number>", "Continuation: stop after this many steps without progress (default 12)")
  .option("--no-continuation", "End a turn at --max-steps instead of continuing while it makes progress")
  .option("-t, --temperature <number>", "Model temperature", "0.2")
  .option("--shell <type>", "Linux shell to use: bash, zsh, or sh (default: bash or $LOCAL_HARNESS_SHELL)", "bash")
  .option("--fallback <urls>", "Comma-separated fallback LLM endpoints if primary is unavailable")
  .option("--context-limit <tokens>", "Context window limit in tokens; below the provider's advertised capacity it is kept, above it the advertised capacity applies (default: advertised capacity, else 65536)")
  .option("--dry-run", "Simulate file modifications without writing changes to disk")
  .option("--read-only", "Reject all mutating tool executions and commands")
  .option("-y, --yes", "Run non-interactively without approval prompts (forces auto mode)")
  .option("--approve", "Require human approval before destructive actions (forces review mode)")
  .option("--mode <mode>", "Execution mode: auto, review, or read-only (default: review; folder trust does not change it)")
  .option("--sandbox [mode]", "Isolate command execution using bubblewrap (bwrap) or Docker (default: auto)")
  .option("--sandbox-network", "With --sandbox: let sandboxed commands and the sandboxed native worker use the network (off by default; also NEXUS_SANDBOX_NETWORK=1 in the operator environment)")
  .option("--worktree", "Isolate execution inside an ephemeral git worktree under .nexus/worktrees/<task-id>")
  .option("--worktree-branch <name>", "Run inside the named git worktree for this branch (created if missing); kept after the run, merge it with `nexus worktree merge`")
  .option("--authoritative-verifier <command>", "Trusted command that must pass before any task completion; its success may authorize automatic worktree merge")
  .option("--deliverable-file <path>", "Operator-declared workspace-relative product file used for VERIFIED binding (repeatable)", collectDeliverableFile, [])
  .option("--record-flight", "Record execution into an append-only deterministic .flightlog")
  .option("--planner-model <name>", "Deep reasoning model for architecture planning (o3, R1, Sonnet)")
  .option("--planner-endpoint <url>", "Dedicated inference endpoint for planner model")
  .option("--coder-model <name>", "High-throughput model for surgical code implementation (Qwen 2.5 Coder)")
  .option("--coder-endpoint <url>", "Dedicated inference endpoint for coder model")
  .option("--tdd", "Enforce strict RED-GREEN-REFACTOR Test-Driven Development protocol")
  .option("--provider <id>", "Cloud inference provider: openrouter, openai, anthropic, compatible (default: appliance endpoint)")
  .option("--base-url <url>", "Override the provider's base URL (operator-only; required for 'compatible')")
  .option("--planner-provider <id>", "Cloud provider for the planner model (requires --planner-model)")
  .option("--coder-provider <id>", "Cloud provider for the coder model (requires --coder-model)")
  .option("-j, --json", "Output machine-readable JSON structured result (UI-002, UI-003)")
  .option("--output <format>", "Output format: text (default), json (same as --json) or stream-json (one JSON event per line, nothing else on stdout; see docs/STREAM_JSON.md)")
  .option("--input-json <file|->", "Read the task from a JSON document { \"schema_version\": 1, \"task\": \"...\" } in a file, or on stdin with '-' (see the manual: nexus run --json)")
  .option("-r, --resume [id]", "Resume previous session or task state")
  .option("--fork-session <id>", "Start in a new copy of the named session (the original is never changed; prints the new id)")
  .option("--fork-at <n>", "With --fork-session: copy only the first n messages (default: all)")
  .option("--answer <id=approve|decline>", "With --resume: answer a question the blocked run asked (the 12-character needsInput.id in its result); for a question that asks for a reply (a blocked requirement), <id>=reply:<text>; repeatable", collectAnswer, [])
  .option("--step", "Execute one model/tool cycle and pause deterministically")
  .action(async (promptParts: string[], _options: any, cmd: Command) => {
    const options = commandOptions(cmd);
    let prompt = promptParts.join(" ").trim();
    const config = buildConfig(options);
    config.surface = "headless";
    let answers: ReturnType<typeof parseOperatorAnswers> | undefined;
    if ((options.answer ?? []).length) {
      try {
        if (options.resume === undefined || options.resume === false) throw new Error("--answer needs --resume (it answers a question a blocked run asked)");
        answers = parseOperatorAnswers(options.answer);
      } catch (err: any) {
        console.error(`error: ${err.message}`);
        exitAfterFlush(runExitCode("usage"));
        return;
      }
    }
    const forkError = forkStartError(options);
    if (forkError) {
      console.error(`error: ${forkError}`);
      exitAfterFlush(runExitCode("usage"));
      return;
    }
    const outputFormat = String(options.output ?? (options.json ? "json" : "text"));
    if (!["text", "json", "stream-json"].includes(outputFormat) || (options.json && outputFormat !== "json")) {
      console.error(options.json && ["text", "stream-json"].includes(outputFormat) ? "error: --json cannot be combined with --output " + outputFormat : "error: --output must be text, json or stream-json");
      exitAfterFlush(runExitCode("usage"));
      return;
    }
    // PF-2: the task may also come from --input-json, or from stdin when no argument is given (src/run_contract.ts).
    try {
      prompt = await resolveRunTask({ prompt, inputJson: options.inputJson, resuming: (options.resume !== undefined && options.resume !== false) || options.forkSession !== undefined, stdin: process.stdin });
    } catch (err: any) {
      console.error(`error: ${redactDiagnosticForOutput(String(err?.message ?? err))}`);
      exitAfterFlush(runExitCode("usage"));
      return;
    }
    const isStream = outputFormat === "stream-json";
    // The event sink writes through the real stdout.write, captured before runTask intercepts stdout for machine output.
    const realStdoutWrite = process.stdout.write.bind(process.stdout);
    const emitEvent = isStream ? streamEventSink((chunk) => realStdoutWrite(chunk)) : undefined;
    const isJson = outputFormat !== "text";

    // Auto-detect loaded model if model is 'local-model' (not on a resume: the task record supplies it, or the first
    // step detects it after the resumed provider wait)
    if (config.model === "local-model" && (options.resume === undefined || options.resume === false) && options.forkSession === undefined) {
      try {
        const client = new LocalLlmClient(config);
        const models = await client.listModels();
        if (models.length > 0) {
          config.model = models[0];
          if (!isJson) {
            console.log(pc.dim(`🔍 Auto-detected active model: ${pc.bold(config.model)}`));
          }
        }
      } catch {
        // Fallback to default
      }
    }

    if (!isJson && (config.provider || config.plannerProvider || config.coderProvider)) console.error(pc.dim(describeTarget(config)));
    const app = new ApplicationCore(config);

    if (options.forkSession !== undefined) {
      try {
        // `run --resume` reads the task store, so the fork is made there (the source is a task id, as for --resume).
        const forked = startFork(new SessionManager(app.getStateManager().getBaseDir(), () => app.getAgent().getWorkspacePathIdentity()), options);
        console.error(forkStartNotice(forked));
        options.resume = forked.id;
      } catch (err: any) {
        console.error(`error: ${redactDiagnosticForOutput(String(err?.message ?? err))}`);
        app.shutdown();
        exitAfterFlush(runExitCode("resume_unavailable"));
        return;
      }
    }

    let resumeTaskId: string | undefined;
    if ((options.resume === undefined || options.resume === false) && !prompt) {
      console.error("error: missing required argument 'prompt'");
      app.shutdown();
      exitAfterFlush(runExitCode("missing_prompt"));
      return;
    }

    // Operator stop authority: first SIGINT cancels the active turn; a second one terminates immediately.
    const abort = new AbortController();
    let sigints = 0;
    const onSigint = () => {
      sigints++;
      if (sigints === 1) {
        abort.abort(new Error("SIGINT"));
        if (!isJson) console.error(pc.yellow("\nInterrupt received: no further work will be started (Ctrl-C again to terminate immediately)."));
      } else {
        process.exit(runExitCode("interrupted"));
      }
    };
    process.on("SIGINT", onSigint);

    try {
      if (options.resume !== undefined && options.resume !== false) {
        if (typeof options.resume === "string" && options.resume !== "latest") {
          resumeTaskId = options.resume;
        } else {
          const targetWorkspace = config.workspace || process.cwd();
          const tasks = app
            .getStateManager()
            .listTasks({ workspace: targetWorkspace })
            .filter((t) => t.taskId !== app.getTaskId());
          if (tasks.length === 0) {
            console.error(`no task to resume in ${formatDiagnosticForOutput(targetWorkspace)}; see 'nexus status'`);
            app.shutdown();
            exitAfterFlush(runExitCode("resume_unavailable"));
            return;
          }
          resumeTaskId = tasks[0].taskId;
        }
        if (!prompt) {
          prompt = options.step ? "" : "continue";
        }
      }
      emitEvent?.("start", { model: config.model, ...(config.provider ? { provider: config.provider } : {}) });
      const result = await app.runTask(prompt, {
        json: isJson,
        ...(emitEvent ? { observer: streamObserver(emitEvent) } : {}),
        resumeTaskId,
        ...(answers?.decisions.size ? { answers: answers.decisions } : {}),
        ...(answers?.replies.size ? { replies: answers.replies } : {}),
        signal: abort.signal,
        step: Boolean(options.step),
      });

      const cloud = UsageLedger.global().cloudTotals();
      if (emitEvent) {
        emitEvent("result", { ...runJsonResult(result, cloud) });
      } else if (isJson) {
        console.log(JSON.stringify(runJsonResult(result, cloud), null, 2));
      } else if (cloud.requests) {
        console.error(pc.dim(UsageLedger.global().summary()!));
      }

      app.shutdown();
      exitAfterFlush(result.exitCode);
    } catch (err: any) {
      if (emitEvent) {
        emitEvent("error", { taskId: app.getTaskId(), message: redactDiagnosticForOutput(String(err?.message ?? err)) });
      } else if (isJson) {
        console.log(JSON.stringify({
          schema_version: RUN_RESULT_SCHEMA_VERSION,
          taskId: app.getTaskId(),
          success: false,
          status: "failed",
          prompt: redactDiagnosticForOutput(prompt),
          output: "",
          plan: [],
          milestones: [],
          validationReceipts: [],
          tokenStats: { prompt: 0, completion: 0, total: 0 },
          durationMs: 0,
          error: redactDiagnosticForOutput(String(err?.message ?? err)),
        }, null, 2));
      } else {
        console.error(pc.red(`\nTask failed: ${formatDiagnosticForOutput(err)}`));
      }
      const exitCode = runExitCode((err instanceof TaskStateNotFoundError || err?.name === "TaskStateNotFoundError") ? "task_not_found" : "failed");
      app.shutdown();
      exitAfterFlush(exitCode);
    }
  });

