79	const invocationKind = clientInvocationKind(startupArgs);
80	const startupReadOnly = invocationKind === "metadata" || (startupArgs[0] === "upgrade" && startupArgs.includes("--check"));
81	let operatorConfigStartupError: Error | undefined;
82	// `upgrade --check` is read-only, so it must not replay a transaction. It also
83	// must not load configuration while a restore journal says that config may be
84	// only partially applied. Refuse before loadEnvironment() and let a normal
85	// managed launch perform recovery.
86	if (startupArgs[0] === "upgrade" && startupArgs.includes("--check")) {
87	  try {
88	    const { hasPendingStateRestore } = await import("./core/state_restore.js");
89	    if (hasPendingStateRestore(process.env.HOME || os.homedir())) {
90	      throw new Error("Pending state restore must be recovered before running upgrade --check");
91	    }
92	  } catch (error: any) {
93	    console.error(`[maintenance] ${formatDiagnosticForOutput(error?.message ?? "Nexus restore state could not be verified")}`);
94	    process.exit(2);
95	  }
96	}
97	// A durable state-restore intent must be replayed before environment/config
98	// loading or any normal client is admitted. The recovery command takes the
99	// exclusive lifetime lease; ordinary clients take their shared lease below.
100	if (invocationKind === "restore" || (invocationKind === "client" && !startupReadOnly)) {
101	  try {
102	    const { hasPendingStateRestore, recoverPendingStateRestore } = await import("./core/state_restore.js");
103	    const home = process.env.HOME || os.homedir();
104	    if (hasPendingStateRestore(home) && !recoverPendingStateRestore(home)) {
105	      throw new Error("Pending state restore could not be recovered; no state was admitted");
106	    }
107	  } catch (error: any) {
108	    console.error(`[maintenance] ${formatDiagnosticForOutput(error?.message ?? "Nexus restore recovery failed closed")}`);
109	    process.exit(2);
110	  }
111	}
112	if (invocationKind === "client") {
113	  try {
114	    const lease = acquireClientLease(process.env.HOME || os.homedir());
115	    process.once("exit", () => releaseClientLease(lease));
116	  } catch (error: any) {
117	    console.error(`[maintenance] ${formatDiagnosticForOutput(error)}`);
118	    process.exit(2);
119	  }
120	  try {
121	    loadEnvironment();
122	  } catch (error: any) {
123	    console.error(`[config] ${formatDiagnosticForOutput(error)}`);
124	    process.exit(2);
125	  }
126	  operatorConfigStartupError = operatorConfigLoadError();
127	}
128	// Release the HOME-scoped client lease before deleting the temporary HOME.
129	if (restoreEvalStartupHome) process.once("exit", restoreEvalStartupHome);
