131	async function recoverInterruptedUpgrade(topLevelCommand: string): Promise<void> {
132	  // Diagnose interrupted upgrades before launching a new CLI/TUI session.
133	  // Read-only version/help/check commands never recover or write state.
134	  if (startupReadOnly || topLevelCommand === "upgrade" || process.env.NEXUS_UPGRADE_HEALTH_CHECK === "1" || !process.env.NEXUS_HOME) return;
135	
136	  const { getJournalPath, readJournal, recoverUpgrade } = await import("./upgrade_journal.js");
137	  const packagedPrefix = path.resolve(process.env.NEXUS_HOME, "../../..");
138	  const journal = readJournal(packagedPrefix);
139	  if ((journal && !["idle", "complete", "rolled_back"].includes(journal.state)) || (!journal && fs.existsSync(getJournalPath(packagedPrefix)))) {
